224: fn tokenize(s: &str) -> Vec<String> {
225:     let mut out = vec![];
226:     let mut cur = String::new();
227:     let mut q: Option<char> = None;
228:     let mut has = false;
229:     let mut it = s.chars().peekable();
230:     while let Some(ch) = it.next() {
231:         match (q, ch) {
232:             (Some(c), x) if x == c => q = None,
233:             (Some(_), x) => cur.push(x),
234:             (None, '"') | (None, '\'') => {
235:                 q = Some(ch);
236:                 has = true;
237:             }
238:             (None, '\\') => {
239:                 if let Some(n) = it.next() {
240:                     cur.push(n);
241:                     has = true;
242:                 }
243:             }
244:             (None, c) if c.is_whitespace() => {
245:                 if has || !cur.is_empty() {
246:                     out.push(std::mem::take(&mut cur));
247:                     has = false;
248:                 }
249:             }
250:             (None, c) => cur.push(c),
251:         }
252:     }
253:     if has || !cur.is_empty() {
254:         out.push(cur);
255:     }
256:     out
257: }
