263:             TLine::Spans(s) => v.push(s.iter().map(|x| x.text.as_str()).collect::<String>()),
264:             TLine::Gap => v.push(String::new()),
265:             TLine::Entries(e) => v.extend(e.iter().map(|x| x.0.clone())),
266:             TLine::Chips(c) => v.push(c.join("  ")),
267:             TLine::Title(a, b) => {
268:                 v.push(a.clone());
269:                 v.push(b.clone());
270:             }
271:         }
272:     }
273:     v
