293: fn calc(expr: &str) -> Result<f64, String> {
294:     struct P<'a> {
295:         s: &'a [u8],
296:         i: usize,
297:     }
298:     impl P<'_> {
299:         fn ws(&mut self) {
300:             while self.i < self.s.len() && self.s[self.i] == b' ' {
301:                 self.i += 1;
302:             }
303:         }
304:         fn expr(&mut self) -> Result<f64, String> {
305:             let mut v = self.term()?;
306:             loop {
307:                 self.ws();
308:                 match self.s.get(self.i) {
309:                     Some(b'+') => {
310:                         self.i += 1;
311:                         v += self.term()?;
312:                     }
313:                     Some(b'-') => {
314:                         self.i += 1;
315:                         v -= self.term()?;
316:                     }
317:                     _ => return Ok(v),
318:                 }
319:             }
320:         }
321:         fn term(&mut self) -> Result<f64, String> {
322:             let mut v = self.pow()?;
323:             loop {
324:                 self.ws();
325:                 match self.s.get(self.i) {
326:                     Some(b'*') | Some(b'x') => {
327:                         self.i += 1;
328:                         v *= self.pow()?;
329:                     }
330:                     Some(b'/') => {
331:                         self.i += 1;
332:                         let d = self.pow()?;
333:                         if d == 0.0 {
334:                             return Err("division by zero".into());
335:                         }
336:                         v /= d;
337:                     }
338:                     Some(b'%') => {
339:                         self.i += 1;
340:                         v %= self.pow()?;
341:                     }
342:                     _ => return Ok(v),
343:                 }
344:             }
345:         }
346:         fn pow(&mut self) -> Result<f64, String> {
347:             let b = self.atom()?;
348:             self.ws();
349:             if self.s.get(self.i) == Some(&b'^') {
350:                 self.i += 1;
351:                 let e = self.pow()?;
352:                 return Ok(b.powf(e));
353:             }
354:             Ok(b)
355:         }
356:         fn atom(&mut self) -> Result<f64, String> {
357:             self.ws();
358:             match self.s.get(self.i) {
359:                 Some(b'(') => {
360:                     self.i += 1;
361:                     let v = self.expr()?;
362:                     self.ws();
363:                     if self.s.get(self.i) != Some(&b')') {
364:                         return Err("missing )".into());
365:                     }
366:                     self.i += 1;
367:                     Ok(v)
368:                 }
369:                 Some(b'-') => {
370:                     self.i += 1;
371:                     Ok(-self.atom()?)
372:                 }
373:                 Some(c) if c.is_ascii_digit() || *c == b'.' => {
374:                     let st = self.i;
375:                     while self.i < self.s.len() && (self.s[self.i].is_ascii_digit() || self.s[self.i] == b'.') {
376:                         self.i += 1;
377:                     }
378:                     std::str::from_utf8(&self.s[st..self.i]).unwrap().parse::<f64>().map_err(|_| "bad number".into())
379:                 }
380:                 _ => Err("unexpected input".into()),
381:             }
382:         }
383:     }
384:     let mut p = P { s: expr.as_bytes(), i: 0 };
385:     let v = p.expr()?;
386:     p.ws();
387:     if p.i != p.s.len() {
388:         return Err("unexpected input".into());
389:     }
390:     Ok(v)
391: }
