393: fn edit_dist(a: &str, b: &str) -> usize {
394:     let (a, b): (Vec<char>, Vec<char>) = (a.chars().collect(), b.chars().collect());
395:     let mut d: Vec<usize> = (0..=b.len()).collect();
396:     for i in 1..=a.len() {
397:         let mut prev = d[0];
398:         d[0] = i;
399:         for j in 1..=b.len() {
400:             let t = d[j];
401:             d[j] = (d[j] + 1).min(d[j - 1] + 1).min(prev + (a[i - 1] != b[j - 1]) as usize);
402:             prev = t;
403:         }
404:     }
405:     d[b.len()]
406: }
