408: impl SmartApp {
409:     pub fn short_path(&self, l: &Location) -> String {
410:         let home = self.be.home();
411:         if l.fs == home.fs && l.starts_with(&home) {
412:             let rest = l.path.strip_prefix(&home.path).unwrap_or("");
413:             return format!("~{}", rest);
414:         }
415:         if l.is_root() { format!("{}:/", l.fs) } else { l.path.clone() }
416:     }
