418:     fn resolve(&self, cwd: &Location, arg: &str) -> Location {
419:         let home = self.be.home();
420:         let (mut cur, rest): (Location, &str) = if arg == "~" {
421:             (home, "")
422:         } else if let Some(r) = arg.strip_prefix("~/") {
423:             (home, r)
424:         } else if let Some(r) = arg.strip_prefix('/') {
425:             (Location::new(cwd.fs.clone(), "/"), r)
426:         } else {
427:             (cwd.clone(), arg)
428:         };
429:         for seg in rest.split('/') {
430:             match seg {
431:                 "" | "." => {}
432:                 ".." => {
433:                     if let Some(p) = cur.parent() {
434:                         cur = p;
435:                     }
436:                 }
437:                 s => cur = cur.join(s),
438:             }
439:         }
440:         cur
441:     }
