449:     fn walk(&self, l: &Location, depth: usize, limit: &mut usize, f: &mut dyn FnMut(&Entry, usize)) {
450:         if let Ok(v) = self.list_dir(l) {
451:             for e in v {
452:                 if *limit == 0 {
453:                     return;
454:                 }
455:                 *limit -= 1;
456:                 f(&e, depth);
457:                 if e.is_dir && depth < 12 {
458:                     self.walk(&e.loc, depth + 1, limit, f);
459:                 }
460:             }
461:         }
462:     }
