482:     /// Run a full command line (pipes + redirect) against the shared backend.
483:     pub fn term_exec_line(&mut self, cwd: &Location, input: &str) -> Out {
484:         let (cmdline, redirect) = if let Some((a, b)) = input.split_once(">>") {
485:             (a.trim().to_string(), Some((b.trim().to_string(), true)))
486:         } else if let Some((a, b)) = input.split_once('>') {
487:             (a.trim().to_string(), Some((b.trim().to_string(), false)))
488:         } else {
489:             (input.trim().to_string(), None)
490:         };
491:         let stages: Vec<String> = cmdline.split(" | ").map(|s| s.trim().to_string()).collect();
492:         let mut stdin: Option<Vec<String>> = None;
493:         let mut last = Out::ok(vec![]);
494:         let mut cd_acc: Option<Location> = None;
495:         let mut acts = vec![];
496:         let mut cur = cwd.clone();
497:         for (i, st) in stages.iter().enumerate() {
498:             let out = self.term_exec_one(&cur, st, stdin.take());
499:             if let Some(c) = &out.cd {
500:                 cur = c.clone();
501:                 cd_acc = Some(c.clone());
502:             }
503:             acts.extend(out.acts.clone());
504:             if out.code != 0 && i + 1 < stages.len() {
505:                 return Out { acts, ..out };
506:             }
507:             stdin = Some(text_of(&out.lines));
508:             last = out;
509:         }
510:         last.acts = acts;
511:         last.cd = cd_acc;
512:         if let Some((target, append)) = redirect {
513:             if target.is_empty() {
514:                 return Out::fail("redirect: missing file name");
515:             }
516:             let dest = self.resolve(&cur, &target);
517:             let mut text = text_of(&last.lines).join("\n");
518:             text.push('\n');
519:             if append {
520:                 if let Ok(old) = self.be.read_text(&dest, 4_000_000) {
521:                     text = format!("{old}{text}");
522:                 }
523:             }
524:             if !self.be.stat(&dest).is_ok() {
525:                 if let Some(parent) = dest.parent() {
526:                     let _ = self.be.create_file(&parent, &dest.name());
527:                 }
528:             }
529:             return match self.be.write_text(&dest, &text) {
530:                 Ok(()) => Out { lines: vec![line(vec![sp(if append { "appended to " } else { "wrote " }, St::Dim), Span { text: self.short_path(&dest), st: St::Accent, link: Some(dest.clone()), bold: false }])], code: 0, cd: last.cd, clear: false, acts: last.acts },
531:                 Err(e) => Out::fail(format!("cannot write {}: {e}", target)),
532:             };
533:         }
534:         last
535:     }
