537:     fn term_exec_one(&mut self, cwd: &Location, cmdline: &str, stdin: Option<Vec<String>>) -> Out {
538:         let toks = tokenize(cmdline);
539:         let Some(cmd) = toks.first().cloned() else { return Out::ok(vec![]) };
540:         let args: Vec<String> = toks[1..].to_vec();
541:         let flags: Vec<&String> = args.iter().filter(|a| a.starts_with('-') && a.len() > 1 && !a[1..].chars().all(|c| c.is_ascii_digit())).collect();
542:         let has = |f: char| flags.iter().any(|a| !a.starts_with("--") && a.contains(f));
543:         let pos: Vec<String> = args.iter().filter(|a| !(a.starts_with('-') && a.len() > 1)).cloned().collect();
544:         let opt_n = |name: &str, default: usize| -> usize { args.iter().position(|a| a == name).and_then(|i| args.get(i + 1)).and_then(|v| v.parse().ok()).unwrap_or(default) };
545:         match cmd.as_str() {
546:             "top" => Out { acts: vec![Act::App("term.full:top".into())], ..Out::ok(vec![line(vec![sp("starting top \u{2014} q to quit", St::Dim)])]) },
547:             "colors" => {
548:                 let mut o = String::from("\x1b[1mStandard\x1b[0m\n");
549:                 for i in 0..16 {
550:                     o.push_str(&format!("\x1b[38;5;{i}m\u{2588}\u{2588}\x1b[0m "));
551:                 }
552:                 o.push_str("\n\n\x1b[1m256 colours\x1b[0m\n");
553:                 for r in 0..6 {
554:                     for i in 16 + r * 36..16 + r * 36 + 36 {
555:                         o.push_str(&format!("\x1b[38;5;{i}m\u{2588}\x1b[0m"));
556:                     }
557:                     o.push('\n');
558:                 }
559:                 o.push_str("\n\x1b[1mTrue colour\x1b[0m\n");
