530:         let lr = self.hit(ui, logo, "tb-logo", Sense::click());
531:         if lr.hovered() || self.shell.menu == Some(0) {
532:             p.rect_filled(logo, cr(7.0), th.row_hover);
533:         }
534:         let lg = Rect::from_center_size(logo.center(), vec2(17.0, 17.0));
535:         let (a, b) = th.accent_grad();
536:         grad_fill(&p, lg, 6.0, a, b);
