538:         p.text(lg.center() + vec2(0.0, 0.5), Align2::CENTER_CENTER, "S", f_bold(10.5), Color32::WHITE);
539:         let mut anchors: Vec<Rect> = vec![logo];
540:         if lr.clicked() {
541:             self.shell.menu = if self.shell.menu == Some(0) { None } else { Some(0) };
542:         }
543:         x = logo.right() + 8.0;
544:         p.text(pos2(x, cy), Align2::LEFT_CENTER, app.name(), f_bold(12.5), ink);
545:         x += self.tw(&p, app.name(), &f_bold(12.5)) + 12.0;
546:         let menus = self.tb_menus(app);
547:         for (i, (label, _)) in menus.iter().enumerate() {
548:             let w = self.tw(&p, label, &f_medium(12.5)) + 18.0;
549:             let r = Rect::from_min_size(pos2(x, cy - 11.0), vec2(w, 22.0));
550:             let resp = self.hit(ui, r, ("tb-menu", i), Sense::click());
551:             let open = self.shell.menu == Some(i + 1);
552:             if resp.hovered() || open {
553:                 p.rect_filled(r, cr(7.0), if open { th.row_press } else { th.row_hover });
554:             }
555:             p.text(r.center(), Align2::CENTER_CENTER, *label, f_medium(12.5), if open || resp.hovered() { ink } else { th.ink2 });
556:             if resp.clicked() {
557:                 self.shell.menu = if open { None } else { Some(i + 1) };
558:             } else if resp.hovered() && self.shell.menu.is_some() && !open {
559:                 self.shell.menu = Some(i + 1);
560:             }
561:             anchors.push(r);
562:             x += w + 2.0;
563:         }
564: 
565:         // right cluster: status icons + clock
566:         let mut rx = bar.right() - 12.0;
567:         let time = clock_hm();
568:         let date = clock_date();
569:         let tf = f_semi(12.5);
570:         let tw_ = self.tw(&p, &time, &tf);
571:         let dw = self.tw(&p, &date, &f_medium(12.5));
572:         let cluster_w = tw_ + dw + 16.0 + 4.0 * 26.0 + 14.0;
