574:         let cresp = self.hit(ui, cluster, "tb-cluster", Sense::click());
575:         if cresp.hovered() || self.shell.qs {
576:             p.rect_filled(cluster, cr(8.0), if self.shell.qs { th.row_press } else { th.row_hover });
577:         }
578:         if cresp.clicked() {
579:             self.shell.qs = !self.shell.qs;
580:             self.shell.menu = None;
581:         }
582:         p.text(pos2(rx, cy), Align2::RIGHT_CENTER, &time, tf, ink);
583:         rx -= tw_ + 10.0;
584:         p.text(pos2(rx, cy), Align2::RIGHT_CENTER, &date, f_medium(12.5), th.ink2);
585:         rx -= dw + 14.0;
586:         let sh = &self.shell;
587:         let status: [(&'static str, bool); 4] = [("battery-charge-minimalistic", true), ("volume-small", sh.volume > 0.02), ("bluetooth", sh.bt), ("wi-fi", sh.wifi)];
588:         for (name, on) in status {
589:             self.ico(&p, name, Ic::Outline, pos2(rx - 9.0, cy), 15.0, if on { th.ink2 } else { alpha(th.ink4, 0.7) });
590:             rx -= 26.0;
