601:                         mi("gallery-wide", "Wallpaper\u{2026}", Act::Seq(vec![Act::OpenApp(AppId::Files), Act::Modal(Modal::Wallpaper)])),
602:                         mi("command", "Command palette", Act::Seq(vec![Act::OpenApp(AppId::Files), Act::Palette])).k("Ctrl+K").gap(),
603:                     ],
604:                     anchors[0],
605:                 )
606:             } else {
607:                 (menus.get(mi_idx - 1).map(|m| m.1.clone()).unwrap_or_default(), anchors.get(mi_idx).copied().unwrap_or(anchors[0]))
608:             };
609:             if !items.is_empty() {
