614:                 let (r, _, act) = self.paint_menu(&mut mp, pos2(anchor.left(), bar.bottom() + 4.0 - (1.0 - pop.min(1.0)) * 6.0), &items, w, "tbm", None);
615:                 if let Some(a) = act {
