617:                     self.acts.push(a);
618:                 } else if ctx.input(|i| i.pointer.primary_pressed()) && ctx.pointer_interact_pos().is_some_and(|pp| !r.contains(pp) && !bar.contains(pp)) {
619:                     self.shell.menu = None;
620:                 }
621:             }
