623:             ctx.data_mut(|d| {
624:                 for i in 0..8 {
625:                     d.remove::<(f32, f32)>(Id::new(("spring", ("tbpop", i))));
626:                 }
627:             });
628:         }
629:         self.draw_quick_settings(ui, screen, bar);
630:     }
