725:     // ───────────── dock ─────────────
726:     fn draw_dock(&mut self, ui: &mut Ui, screen: Rect) {
727:         #[derive(Clone, Copy)]
728:         enum Di {
729:             App(AppId),
730:             Sep,
731:             Palette,
732:             Settings,
733:         }
734:         let ctx = ui.ctx().clone();
735:         let th = self.th.clone();
736:         let p = ui.painter().clone();
737:         let items = [Di::App(AppId::Files), Di::App(AppId::Photos), Di::App(AppId::Terminal), Di::App(AppId::Video), Di::Sep, Di::Settings, Di::Palette];
738:         let (base, gap, pad) = (46.0f32, 8.0f32, 12.0f32);
739:         let n = items.len();
740:         let w0: f32 = items.iter().map(|i| if matches!(i, Di::Sep) { 10.0 } else { base }).sum::<f32>() + gap * (n as f32 - 1.0) + pad * 2.0;
741:         let left0 = screen.center().x - w0 / 2.0;
742:         let ptr = ctx.input(|i| i.pointer.hover_pos());
743:         let zone = Rect::from_min_max(pos2(left0 - 30.0, screen.bottom() - DOCK_H), pos2(left0 + w0 + 30.0, screen.bottom()));
744:         let in_zone = ptr.is_some_and(|pp| zone.contains(pp));
745:         // magnification targets from the un-magnified centres
746:         let mut cx0 = left0 + pad;
747:         let mut scales = vec![];
748:         for (i, it) in items.iter().enumerate() {
749:             let w = if matches!(it, Di::Sep) { 10.0 } else { base };
750:             let c0 = cx0 + w / 2.0;
751:             let tgt = match (it, ptr) {
752:                 (Di::Sep, _) => 1.0,
753:                 (_, Some(pp)) if in_zone => 1.0 + 0.62 * (-((pp.x - c0) / 62.0).powi(2)).exp(),
754:                 _ => 1.0,
755:             };
756:             scales.push(spring_to(&ctx, ("dock-s", i), tgt, 320.0, 25.0));
757:             cx0 += w + gap;
758:         }
759:         let total: f32 = items.iter().zip(&scales).map(|(it, s)| if matches!(it, Di::Sep) { 10.0 } else { base * s }).sum::<f32>() + gap * (n as f32 - 1.0) + pad * 2.0;
760:         let left = screen.center().x - total / 2.0;
