151:     /// iOS-style switch with spring knob.
152:     pub fn switch(&self, ui: &Ui, r: Rect, on: bool, id: impl std::hash::Hash + std::fmt::Debug + Copy) -> bool {
153:         let th = &self.th;
154:         let p = ui.painter();
155:         let resp = self.hit(ui, r, ("sw", id), Sense::click());
156:         let t = spring_to(ui.ctx(), ("swk", id), if on { 1.0 } else { 0.0 }, 420.0, 26.0);
157:         let ct = t.clamp(0.0, 1.0);
158:         well(p, th, r, r.height() / 2.0);
159:         if ct > 0.01 {
160:             let (a, b) = th.accent_grad();
161:             let f = Rect::from_min_size(r.min, vec2(r.height() + (r.width() - r.height()) * ct, r.height()));
162:             grad_fill(p, f, r.height() / 2.0, alpha(a, ct), alpha(b, ct));
163:             rim(p, f, r.height() / 2.0, 1.0, Color32::from_white_alpha(100), true, 8.0);
164:         }
165:         let k = r.height() - 6.0 + if resp.is_pointer_button_down_on() { 3.0 } else { 0.0 };
166:         let cx = r.left() + 3.0 + k / 2.0 + (r.width() - r.height()) * t;
167:         let knob = Rect::from_center_size(pos2(cx, r.center().y), vec2(k, r.height() - 6.0));
168:         raised(p, th, knob, (r.height() - 6.0) / 2.0, resp.hovered(), false);
169:         resp.clicked() != false && true
170:     }
