172:     /// Horizontal slider (0..1) with a recessed track and a raised knob. Returns the (possibly new) value.
173:     pub fn slider(&self, ui: &Ui, track: Rect, v: f32, id: impl std::hash::Hash + std::fmt::Debug + Copy) -> (f32, Response) {
174:         let th = &self.th;
175:         let p = ui.painter();
176:         let resp = self.hit(ui, track.expand2(vec2(9.0, 10.0)), ("sl", id), Sense::click_and_drag());
177:         let mut nv = v;
178:         if resp.dragged() || resp.clicked() {
179:             if let Some(pp) = resp.interact_pointer_pos() {
180:                 nv = ((pp.x - track.left()) / track.width()).clamp(0.0, 1.0);
181:             }
182:         }
183:         let shown = spring_to(ui.ctx(), ("slk", id), nv, 420.0, 32.0).clamp(0.0, 1.0);
184:         let h = track.height();
185:         well(p, th, track, h / 2.0);
186:         let fill = Rect::from_min_size(track.min, vec2((track.width() * shown).max(h), h));
187:         let (c0, c1) = th.accent_grad();
188:         grad_fill(p, fill, h / 2.0, c0, c1);
189:         rim(p, fill, h / 2.0, 1.0, Color32::from_white_alpha(110), true, 6.0);
190:         let kd = h + 8.0;
191:         let knob = Rect::from_center_size(pos2(track.left() + h / 2.0 + (track.width() - h) * shown, track.center().y), vec2(kd, kd) * if resp.dragged() { 1.12 } else { 1.0 });
192:         raised(p, th, knob, kd / 2.0, resp.hovered(), resp.dragged());
193:         (nv, resp)
194:     }
