196:     /// Segmented control: recessed track and a raised pill that travels on a spring, stretching with its speed
197:     /// (squash and stretch), pressing in under the finger, with labels and icons easing between states.
198:     pub fn segment(&self, ui: &Ui, r: Rect, opts: &[(&'static str, &str)], icons: bool, sel: usize, id: &str) -> Option<usize> {
199:         let th = &self.th;
200:         let p = ui.painter();
201:         let ctx = ui.ctx();
202:         let n = opts.len().max(1);
203:         well(p, th, r, r.height() / 2.0);
204:         let cw = (r.width() - 6.0) / n as f32;
205:         let x = spring_to(ctx, ("seg", id), sel as f32, 330.0, 21.0);
206:         let key = Id::new(("seg-prev", id));
207:         let prev: f32 = ctx.data_mut(|d| d.get_temp(key)).unwrap_or(x);
208:         ctx.data_mut(|d| d.insert_temp(key, x));
209:         let speed = (x - prev).abs();
210:         let stretch = (speed * 5.0).min(0.42);
211:         if speed > 0.0005 {
212:             ctx.request_repaint();
213:         }
214:         let any_down = (0..n).any(|i| ui.rect_contains_pointer(Rect::from_min_size(pos2(r.left() + 3.0 + cw * i as f32, r.top()), vec2(cw, r.height()))) && ui.input(|i| i.pointer.primary_down()));
215:         let press = spring_to(ctx, ("segp", id), if any_down { 1.0 } else { 0.0 }, 520.0, 30.0).clamp(0.0, 1.0);
216:         let w = cw * (1.0 + stretch) - press * 3.0;
217:         let h = r.height() - 6.0 - press * 2.0;
218:         let cx = r.left() + 3.0 + cw * x + cw / 2.0;
219:         let pill = Rect::from_center_size(pos2(cx, r.center().y), vec2(w, h));
220:         raised(p, th, pill, pill.height() / 2.0, false, any_down);
221:         let mut out = None;
222:         for (i, (icon, label)) in opts.iter().enumerate() {
223:             let cell = Rect::from_min_size(pos2(r.left() + 3.0 + cw * i as f32, r.top() + 3.0), vec2(cw, r.height() - 6.0));
224:             let resp = self.hit(ui, cell, ("segc", id, i), Sense::click());
225:             let on = i == sel;
226:             let a = self.anim(ui, ("segh", id, i), resp.hovered());
227:             let t = spring_to(ctx, ("segt", id, i), if on { 1.0 } else { 0.0 }, 300.0, 24.0).clamp(0.0, 1.0);
228:             let col = mix(mix(th.ink3, th.ink1, a), th.accent_ink, t);
229:             if icons {
230:                 let pop = 16.0 + 2.5 * t;
231:                 self.ico(p, icon, if on { Ic::Duo } else { Ic::Outline }, cell.center() - vec2(0.0, t * 0.6), pop, col);
232:                 if !label.is_empty() {
233:                     resp.clone().on_hover_text(*label);
234:                 }
235:             } else {
236:                 p.text(cell.center(), Align2::CENTER_CENTER, *label, if on { f_semi(T_META) } else { f_medium(T_META) }, col);
237:             }
238:             if resp.clicked() && !on {
239:                 out = Some(i);
240:             }
241:         }
242:         out
243:     }
