251:     pub fn draw_app_menu(&mut self, ui: &mut Ui, screen: Rect) {
252:         let Some(m) = self.shell.appmenu.as_ref() else { return };
253:         let items = Self::tidy_menu(m.items.clone());
254:         let (mut pos, age) = (m.pos, (self.time - m.born) as f32);
255:         if items.is_empty() {
256:             self.shell.appmenu = None;
257:             return;
258:         }
259:         let p = ui.painter().clone();
260:         let w = self.menu_width(&p, &items, 232.0);
261:         let h = Self::menu_height(&items);
262:         pos.x = pos.x.min(screen.right() - w - 8.0).max(screen.left() + 8.0);
263:         pos.y = if pos.y + h > screen.bottom() - 8.0 { (screen.bottom() - h - 8.0).max(screen.top() + TOP_PAD) } else { pos.y };
264:         let pop = if self.lib(|l| l.settings.reduce_motion) { 1.0 } else { spring_out(age) };
265:         pos.y += (1.0 - pop) * -9.0;
266:         if age < 0.5 {
267:             ui.ctx().request_repaint();
268:         }
269:         let mut mp = ui.new_child(egui::UiBuilder::new().max_rect(screen));
270:         mp.set_opacity((age * 9.0).clamp(0.0, 1.0));
271:         let open_sub = ui.ctx().data_mut(|d| d.get_temp::<Option<usize>>(Id::new("appmenu-sub"))).flatten();
272:         let (r, hs, act) = self.paint_menu(&mut mp, pos, &items, w, "am", open_sub);
273:         let mut inside = mp.rect_contains_pointer(r);
274:         let mut chosen = act;
275:         let mut next_sub = None;
276:         if let Some(si) = hs.or(open_sub) {
277:             if let Some(row) = items.get(si) {
278:                 if !row.sub.is_empty() {
279:                     let row_y = pos.y + Self::menu_row_y(&items, si);
280:                     let sub = Self::tidy_menu(row.sub.clone());
281:                     let sw = self.menu_width(&p, &sub, 210.0);
282:                     let sh = Self::menu_height(&sub);
283:                     let mut sp = pos2(r.right() + 4.0, row_y);
284:                     if sp.x + sw > screen.right() - 8.0 {
285:                         sp.x = r.left() - sw - 4.0;
286:                     }
287:                     sp.y = sp.y.min(screen.bottom() - sh - 8.0).max(screen.top() + 4.0);
288:                     let (sr, _, sact) = self.paint_menu(&mut mp, sp, &sub, sw, "ams", None);
289:                     if sact.is_some() {
290:                         chosen = sact;
291:                     }
292:                     let over_row = mp.rect_contains_pointer(Rect::from_min_size(pos2(r.left(), row_y), vec2(w, 34.0)));
293:                     let over_sub = mp.rect_contains_pointer(sr);
294:                     inside = inside || over_sub;
295:                     next_sub = if hs.is_some() || over_sub || (over_row && open_sub.is_some()) { Some(si) } else { None };
296:                 }
297:             }
298:         }
299:         ui.ctx().data_mut(|d| d.insert_temp(Id::new("appmenu-sub"), next_sub));
300:         let pressed = ui.ctx().input(|i| i.pointer.primary_pressed() || i.pointer.secondary_pressed());
301:         let esc = ui.ctx().input(|i| i.key_pressed(egui::Key::Escape));
302:         if let Some(a) = chosen {
303:             self.shell.appmenu = None;
304:             self.acts.push(a);
305:         } else if esc || (pressed && !inside && age > 0.05) {
306:             self.shell.appmenu = None;
307:         }
308:     }
