446:     /// Eight invisible resize handles around a window. Returns the drag direction and delta of the active one.
447:     pub fn resize_handles(&self, ui: &Ui, key: impl std::hash::Hash + std::fmt::Debug + Copy, r: Rect) -> Option<((f32, f32), egui::Vec2)> {
448:         let (ei, eo, k) = (3.0, 7.0, 18.0);
449:         use egui::CursorIcon as C;
450:         let zones: [(Rect, C, (f32, f32)); 8] = [
451:             (Rect::from_min_max(pos2(r.right() - ei, r.top() + k), pos2(r.right() + eo, r.bottom() - k)), C::ResizeHorizontal, (1.0, 0.0)),
452:             (Rect::from_min_max(pos2(r.left() - eo, r.top() + k), pos2(r.left() + ei, r.bottom() - k)), C::ResizeHorizontal, (-1.0, 0.0)),
453:             (Rect::from_min_max(pos2(r.left() + k, r.bottom() - ei), pos2(r.right() - k, r.bottom() + eo)), C::ResizeVertical, (0.0, 1.0)),
454:             (Rect::from_min_max(pos2(r.left() + k, r.top() - eo), pos2(r.right() - k, r.top() + 2.0)), C::ResizeVertical, (0.0, -1.0)),
455:             (Rect::from_min_max(pos2(r.right() - k, r.bottom() - k), pos2(r.right() + eo, r.bottom() + eo)), C::ResizeNwSe, (1.0, 1.0)),
456:             (Rect::from_min_max(pos2(r.left() - eo, r.bottom() - k), pos2(r.left() + k, r.bottom() + eo)), C::ResizeNeSw, (-1.0, 1.0)),
457:             (Rect::from_min_max(pos2(r.right() - k, r.top() - eo), pos2(r.right() + eo, r.top() + k)), C::ResizeNeSw, (1.0, -1.0)),
458:             (Rect::from_min_max(pos2(r.left() - eo, r.top() - eo), pos2(r.left() + k, r.top() + k)), C::ResizeNwSe, (-1.0, -1.0)),
459:         ];
460:         let mut out = None;
461:         for (zi, (zr, cur, dir)) in zones.iter().enumerate() {
462:             let resp = ui.interact(*zr, Id::new(("resize", key, zi)), Sense::drag());
463:             if resp.hovered() || resp.dragged() {
464:                 ui.ctx().set_cursor_icon(*cur);
465:             }
466:             if resp.dragged() {
467:                 out = Some((*dir, resp.drag_delta()));
468:             }
469:         }
470:         out
471:     }
