1255:                                     (Some(i), true) => Some(i.saturating_sub(1)),
1256:                                     (Some(i), false) if i + 1 < h.len() => Some(i + 1),
1257:                                     (Some(_), false) => None,
1258:                                     (None, false) => None,
1259:                                 };
1260:                                 s.hist_i = next;
1261:                                 s.input = next.map(|i| h[i].clone()).unwrap_or_else(|| s.draft.clone());
1262:                                 s.cursor = s.input.chars().count();
1263:                             }
1264:                             edited = false;
1265:                         }
1266:                         Key::Tab => {
1267:                             self.term_complete(si);
1268:                             edited = false;
1269:                         }
1270:                         Key::Escape => {
1271:                             s.cands.clear();
1272:                             s.cand_i = None;
1273:                             edited = false;
1274:                         }
1275:                         Key::L if ctrl => s.blocks.clear(),
1276:                         Key::U if ctrl => {
1277:                             s.input = s.input.chars().skip(s.cursor).collect();
1278:                             s.cursor = 0;
1279:                         }
1280:                         Key::K if ctrl => s.input = s.input.chars().take(s.cursor).collect(),
1281:                         Key::A if ctrl => {
1282:                             s.cursor = 0;
1283:                             edited = false;
1284:                         }
1285:                         Key::E if ctrl => {
1286:                             s.cursor = n;
1287:                             edited = false;
1288:                         }
1289:                         Key::Plus | Key::Equals if ctrl => {
1290:                             self.shell.term.font = (self.shell.term.font + 1.0).min(20.0);
1291:                             edited = false;
1292:                         }
1293:                         Key::Minus if ctrl => {
1294:                             self.shell.term.font = (self.shell.term.font - 1.0).max(10.0);
1295:                             edited = false;
1296:                         }
1297:                         _ => edited = false,
1298:                     }
1299:                     if edited && key != Key::Enter && si < self.shell.term.sessions.len() {
1300:                         let s = &mut self.shell.term.sessions[si];
1301:                         s.cands.clear();
1302:                         s.cand_i = None;
1303:                     }
1304:                     continue;
1305:                 }
1306:                 _ => {
1307:                     edited = false;
1308:                 }
1309:             }
1310:             if edited && si < self.shell.term.sessions.len() {
1311:                 let s = &mut self.shell.term.sessions[si];
1312:                 s.cands.clear();
1313:                 s.cand_i = None;
1314:                 s.hist_i = None;
1315:                 s.to_bottom = true;
1316:             }
1317:         }
1318:     }
