1322:         match st {
1323:             St::Plain => tc("#dbe4f5", "#1c2740"),
1324:             St::Dim => tc("#7d89a3", "#6b768e"),
1325:             St::Accent => tc("#8db4ff", "#2f62d0"),
1326:             St::Good => tc("#6fd9a8", "#1f8a5e"),
1327:             St::Warn => tc("#f2c166", "#a8700c"),
1328:             St::Err => tc("#ff8c97", "#c0364a"),
1329:             St::Dir => tc("#8db4ff", "#2f62d0"),
1330:             St::Pink => tc("#f29bd0", "#b0368c"),
1331:             St::Rgb(c) => c,
1332:         }
1333:     }
