1809: // ───────────────────────────── real terminal emulation (vt100) ─────────────────────────────
1810: thread_local! {
1811:     static TDARK: std::cell::Cell<bool> = const { std::cell::Cell::new(true) };
1812: }
1813: fn td() -> bool {
1814:     TDARK.with(|c| c.get())
1815: }
1816: /// Colour that adapts to the theme: (dark value, light value).
1817: fn tc(dark: &str, light: &str) -> Color32 {
1818:     hex(if td() { dark } else { light })
1819: }
1820: /// Overlay tint for depth on the surface: light on dark themes, ink on light themes.
1821: fn ovc() -> Color32 {
1822:     if td() { Color32::WHITE } else { hex("#14203a") }
1823: }
1824: 
1825: fn idx_color(i: u8, bold: bool) -> Color32 {
1826:     let dark = td();
1827:     let base: [&str; 16] = if dark {
1828:         ["#4a5468", "#ff7b86", "#6fd9a8", "#f2c166", "#7fa8ff", "#e08cff", "#6fd7e6", "#dbe4f5", "#7d89a3", "#ff9aa5", "#8cebc0", "#ffd88a", "#9dbdff", "#eaa8ff", "#8ee6f2", "#ffffff"]
1829:     } else {
1830:         ["#2b3550", "#c0364a", "#1f8a5e", "#a8700c", "#2f62d0", "#9a3fc8", "#13808f", "#6b768e", "#5a6680", "#d4475b", "#25a06f", "#bb8110", "#4577e6", "#ae52dc", "#1b97a8", "#111a2e"]
1831:     };
1832:     let i = if bold && i < 8 { i + 8 } else { i };
1833:     match i {
1834:         0..=15 => hex(base[i as usize]),
1835:         16..=231 => {
1836:             let n = i - 16;
1837:             let l = |v: u8| if v == 0 { 0 } else { 55 + 40 * v };
1838:             Color32::from_rgb(l(n / 36), l((n / 6) % 6), l(n % 6))
1839:         }
1840:         _ => {
1841:             let g = 8 + 10 * (i - 232);
1842:             Color32::from_gray(g)
1843:         }
1844:     }
1845: }
1846: 
1847: pub(crate) fn ansi_rgb(c: vt100::Color, bold: bool) -> Option<Color32> {
1848:     match c {
1849:         vt100::Color::Default => None,
1850:         vt100::Color::Rgb(r, g, b) => Some(Color32::from_rgb(r, g, b)),
1851:         vt100::Color::Idx(i) => Some(idx_color(i, bold)),
1852:     }
1853: }
1854: 
1855: /// Run raw ANSI text through the vt100 state machine and turn the resulting screen into styled lines.
1856: pub fn ansi_lines(text: &str) -> Vec<TLine> {
1857:     let n = text.split('\n').count();
1858:     let mut p = vt100::Parser::new((n as u16 + 2).clamp(2, 1500), 240, 0);
1859:     p.process(text.replace('\n', "\r\n").as_bytes());
1860:     let scr = p.screen();
1861:     let (rows, cols) = scr.size();
1862:     let mut out: Vec<TLine> = vec![];
1863:     for r in 0..rows {
1864:         let mut spans: Vec<Span> = vec![];
1865:         for c in 0..cols {
1866:             let Some(cell) = scr.cell(r, c) else { continue };
1867:             if cell.is_wide_continuation() {
1868:                 continue;
1869:             }
1870:             let ch = if cell.has_contents() { cell.contents() } else { " ".to_string() };
1871:             let st = ansi_rgb(cell.fgcolor(), cell.bold()).map(St::Rgb).unwrap_or(St::Plain);
1872:             let bold = cell.bold();
1873:             match spans.last_mut() {
1874:                 Some(l) if l.st == st && l.bold == bold => l.text.push_str(&ch),
1875:                 _ => spans.push(Span { text: ch, st, link: None, bold }),
1876:             }
1877:         }
1878:         if let Some(l) = spans.last_mut() {
1879:             l.text = l.text.trim_end().to_string();
1880:         }
1881:         spans.retain(|s| !s.text.is_empty());
1882:         out.push(TLine::Spans(spans));
1883:     }
1884:     while matches!(out.last(), Some(TLine::Spans(s)) if s.is_empty()) {
1885:         out.pop();
1886:     }
1887:     out
1888: }
