1897: fn top_frame(t: f64, cols: usize, rows: usize, tasks: usize) -> String {
1898:     let mut o = String::from("\x1b[?25l\x1b[2J\x1b[H");
1899:     let bw = (cols.saturating_sub(34) / 2).clamp(8, 36);
1900:     let bar = |label: &str, v: f32| -> String {
1901:         let n = (v * bw as f32).round() as usize;
1902:         let col = if v < 0.5 { "32" } else if v < 0.8 { "33" } else { "31" };
1903:         format!("\x1b[1;36m{label:<4}\x1b[0m[\x1b[{col}m{}\x1b[90m{}\x1b[0m] \x1b[1m{:>4.1}%\x1b[0m", "|".repeat(n), "|".repeat(bw - n), v * 100.0)
1904:     };
1905:     o.push_str(&format!("\x1b[1;34mSmart Terminal\x1b[0m \x1b[90mtop\x1b[0m  tasks: \x1b[1m{tasks}\x1b[0m   up {:.0}s\r\n", t + 3600.0));
1906:     for c in 0..4 {
1907:         let v = (0.42 + 0.38 * (t * (0.6 + c as f64 * 0.23) + c as f64 * 1.7).sin() + 0.1 * (t * 3.1 + c as f64).sin()).clamp(0.03, 0.99) as f32;
1908:         o.push_str(&bar(&format!("CPU{c}"), v));
1909:         o.push_str("\r\n");
1910:     }
1911:     o.push_str(&bar("Mem", (0.58 + 0.04 * (t * 0.4).sin()) as f32));
1912:     o.push_str("\r\n");
1913:     o.push_str(&bar("Swp", 0.07));
1914:     o.push_str("\r\n\r\n");
1915:     o.push_str("\x1b[7m  PID USER       CPU%   MEM%  COMMAND");
1916:     o.push_str(&" ".repeat(cols.saturating_sub(40)));
1917:     o.push_str("\x1b[0m\r\n");
1918:     let procs = [("smart-files", 14.0, 6.2), ("smart-photos", 9.0, 8.8), ("egui-render", 22.0, 3.1), ("wasm-vm", 17.0, 11.4), ("smart-terminal", 4.0, 1.9), ("vfs-indexer", 7.0, 2.4), ("thumbnailer", 11.0, 4.7), ("audio-engine", 3.0, 1.2), ("compositor", 6.0, 3.9), ("zip-worker", 2.0, 0.8), ("clipboardd", 0.4, 0.2), ("syncd", 1.1, 0.6)];
1919:     let mut v: Vec<(usize, &str, f64, f64)> = procs.iter().enumerate().map(|(i, (n, c, m))| (i, *n, (c * (0.65 + 0.35 * (t * 0.8 + i as f64 * 1.3).sin())).max(0.1), *m)).collect();
1920:     v.sort_by(|a, b| b.2.partial_cmp(&a.2).unwrap());
1921:     for (i, n, cpu, mem) in v.into_iter().take(rows.saturating_sub(11)) {
1922:         let col = if cpu > 15.0 { "31" } else if cpu > 8.0 { "33" } else { "32" };
1923:         o.push_str(&format!("{:>5} naledzi \x1b[{col}m{:>6.1}\x1b[0m {:>6.1}  \x1b[1;37m{n}\x1b[0m\r\n", 1200 + i * 37, cpu, mem));
1924:     }
1925:     o.push_str(&format!("\x1b[{};1H\x1b[7m q \x1b[0m quit   \x1b[7m Esc \x1b[0m close   \x1b[90mvt100 screen\x1b[0m", rows.max(1)));
1926:     o
1927: }
