1942:     pub fn term_cmd(&mut self, c: &str) {
1943:         if self.shell.term.sessions.is_empty() {
1944:             self.shell.term.command(c);
1945:             return;
1946:         }
1947:         let si = self.shell.term.active.min(self.shell.term.sessions.len() - 1);
1948:         let (name, arg) = c.split_once(':').unwrap_or((c, ""));
1949:         let blk = self.shell.term.ctx_block.take();
1950:         match name {
1951:             "run" => {
1952:                 let cmd = if arg == "!!" { self.shell.term.history.last().cloned().unwrap_or_default() } else { arg.to_string() };
1953:                 self.term_submit(si, cmd);
1954:             }
1955:             "go" => {
1956:                 if let Some(pl) = arg.parse::<usize>().ok().and_then(|i| self.places.get(i).cloned()) {
1957:                     self.term_submit(si, format!("cd {}", quote(&pl.loc.path)));
1958:                 }
1959:             }
1960:             "fill" => {
1961:                 let s = &mut self.shell.term.sessions[si];
1962:                 s.input = arg.to_string();
1963:                 s.cursor = s.input.chars().count();
1964:                 s.to_bottom = true;
1965:             }
1966:             "full" => {
1967:                 let mut parser = vt100::Parser::new(30, 100, 0);
1968:                 parser.process(b"");
1969:                 let t = self.time;
1970:                 self.shell.term.sessions[si].full = Some(FullApp { kind: "top", parser, t0: t, last: -10.0 });
1971:             }
1972:             "copy_cmd" | "copy_out" | "copy_all" => {
1973:                 if let Some((s, b)) = blk {
1974:                     if let Some(bl) = self.shell.term.sessions.get(s).and_then(|x| x.blocks.get(b)) {
1975:                         let out = text_of(&bl.lines).join("\n");
1976:                         let t = match name {
1977:                             "copy_cmd" => bl.cmd.clone(),
1978:                             "copy_out" => out,
1979:                             _ => format!("$ {}\n{}", bl.cmd, out),
1980:                         };
1981:                         self.acts.push(Act::CopyText(t));
1982:                         self.toast("Copied", true);
1983:                     }
1984:                 }
1985:             }
1986:             "copy_last" => {
1987:                 if let Some(bl) = self.shell.term.sessions[si].blocks.iter().rev().find(|b| !b.cmd.is_empty()) {
1988:                     let t = text_of(&bl.lines).join("\n");
1989:                     self.acts.push(Act::CopyText(t));
1990:                     self.toast("Last output copied", true);
1991:                 }
1992:             }
