219: /// Closed-form damped spring step response (0 → 1 with a little overshoot). `t` in seconds.
220: pub fn spring_out(t: f32) -> f32 {
221:     if t <= 0.0 {
222:         return 0.0;
223:     }
224:     let (w, z) = (26.0f32, 0.62f32);
225:     let wd = w * (1.0 - z * z).sqrt();
226:     1.0 - (-z * w * t).exp() * ((wd * t).cos() + z / (1.0 - z * z).sqrt() * (wd * t).sin())
227: }
