229: /// Stateful spring per `id`, stored in egui memory. Returns the current value; keeps repainting until at rest.
230: pub fn spring_to(ctx: &egui::Context, id: impl std::hash::Hash + std::fmt::Debug, target: f32, stiffness: f32, damping: f32) -> f32 {
231:     let key = egui::Id::new(("spring", id));
232:     let dt = ctx.input(|i| i.stable_dt).min(0.05);
233:     let (mut x, mut v) = ctx.data_mut(|d| d.get_temp::<(f32, f32)>(key)).unwrap_or((target, 0.0));
234:     // semi-implicit Euler, sub-stepped for stability
235:     let n = 3;
236:     for _ in 0..n {
237:         let h = dt / n as f32;
238:         v += (-stiffness * (x - target) - damping * v) * h;
239:         x += v * h;
240:     }
241:     if (x - target).abs() < 0.0006 && v.abs() < 0.004 {
242:         x = target;
243:         v = 0.0;
244:     } else {
245:         ctx.request_repaint();
246:     }
247:     ctx.data_mut(|d| d.insert_temp(key, (x, v)));
248:     x
249: }

