190: pub fn color(c: Cls, dark: bool) -> Color32 {
191:     let (d, l) = match c {
192:         Cls::Plain => ((0xd8, 0xe2, 0xf2), (0x22, 0x2b, 0x3d)),
193:         Cls::Keyword => ((0xc7, 0x92, 0xea), (0x8a, 0x3f, 0xc4)),
194:         Cls::Function => ((0x82, 0xaa, 0xff), (0x1f, 0x5f, 0xd6)),
195:         Cls::Type => ((0xff, 0xcb, 0x6b), (0xa6, 0x6a, 0x00)),
196:         Cls::Str => ((0xc3, 0xe8, 0x8d), (0x2a, 0x7d, 0x32)),
197:         Cls::Number => ((0xf7, 0x8c, 0x6c), (0xc2, 0x4a, 0x1d)),
198:         Cls::Comment => ((0x6c, 0x7f, 0x9c), (0x7a, 0x86, 0x9c)),
199:         Cls::Punct => ((0x89, 0xdd, 0xff), (0x3b, 0x7d, 0x9e)),
200:         Cls::Property => ((0xf0, 0x71, 0x78), (0xc1, 0x32, 0x3a)),
201:         Cls::Tag => ((0xf0, 0x71, 0x78), (0xc1, 0x32, 0x3a)),
202:         Cls::Title => ((0x82, 0xaa, 0xff), (0x1f, 0x5f, 0xd6)),
203:         Cls::Link => ((0x80, 0xcb, 0xc4), (0x0e, 0x7c, 0x75)),
204:         Cls::Escape => ((0x89, 0xdd, 0xff), (0x3b, 0x7d, 0x9e)),
205:     };
206:     let (r, g, b) = if dark { d } else { l };
207:     Color32::from_rgb(r, g, b)
208: }
