629: # ═══════════════════════════════════════════════════════════════════════
630: # Virtual Terminal Multiplexing
631: #
632: # An OS typically needs several concurrent consoles at once, and they are
633: # not interchangeable: an emergency shell must stay available when
634: # everything else has crashed, a boot surface exists only until a session
635: # manager takes over, a log sink is write-mostly, and an interactive
636: # console is what a user actually types at.
637: #
638: # Those are ROLES, and the set of roles is not closed by mathematics —
639: # so the role is an open token, not an enum. The previous revision named
640: # one platform's console architecture inside the enum and inside the
641: # required-field examples (its device-node names, its kernel log device,
642: # and two remote-attachment protocols). That is exactly the
643: # platform-leak the file's own header forbids, and it left a 2046
644: # console with no way to say what it is except `custom @7`.
645: #
646: # The multiplexing service hands out one ConsoleSession per logical
647: # console. Sessions are independent input/output, may be focused one at
648: # a time, and may rebind to different output backends.
649: # ═══════════════════════════════════════════════════════════════════════
650: 
651: struct ConsoleSession {
652:     # Session identifier (issued by the multiplexer, stable).
653:     handle @0 :UInt64;
654:     # Human label — free text chosen by whoever opened the session.
655:     # Deliberately open: a label is a display string, not an identifier
656:     # any client must parse, and a backend may not have a device node to
657:     # name. Unknown labels are ignored by consumers, never rejected.
658:     label @1 :Text;
659:     # Open role token. A backend names its own roles; a consumer that
660:     # does not recognise a token skips it (ai.capnp:43-47). The roles a
661:     # general OS contract can state today:
662:     #   "interactive"   — a console a user types at
663:     #   "log"           — a write-mostly diagnostic sink
664:     #   "boot"          — a surface that exists until a session manager
665:     #                     takes over
666:     #   "emergency"     — always available, even when other consoles fail
667:     #   "debug"         — operator-attached, hot-pluggable
668:     # Anything else a backend invents rides in this same open field.
669:     class @2 :Text;
670:     # Encoding for text I/O.
671:     encoding @3 :Text;
672:     # Logical geometry in cells.
673:     columns @4 :UInt32;
674:     rows @5 :UInt32;
675:     # Whether the session is currently held by a focus owner.
676:     focused @6 :Bool;
677: }
678: 
679: # ── AUTHORITY — READ THIS BEFORE ADDING A PERMISSION FIELD ──────────────
680: # The previous revision carried `permissions :UInt32` beside an enum that
681: # named six permission values and assigned none of them a bit. The field
682: # was therefore required, unreadable across backends, and a second
683: # authority describing what the session reference already grants.
684: #
685: # It is deleted, not repaired. Authority is the interface reference: the
686: # ConsoleSession you hold IS what you may do with that session, gated
687: # once at acquisition (DESIGN_PRINCIPLES.md:394, ai.capnp:49-60). A
688: # client that may read holds a readable session; a client that may not
689: # was never handed one. There is no bit to set, and therefore no bit to
690: # disagree about.
691: 
692: # ── Multiplexing Service ─────────────────────────────────────
693: # Hands out sessions; arbitrates focus; routes I/O.
694: 
695: interface ConsoleMultiplexer {
696:     # List sessions currently available.
697:     listSessions @0 () -> (sessions :List(ConsoleSession));
698:     # Open a session by label.
699:     open @1 (label :Text) -> (session :ConsoleSession);
700:     # Close a session (releases its focus, releases any subscribers).
701:     close @2 (handle :UInt64) -> (result :T.VoidResult);
702:     # Read input from a session; cancels when closed.
703:     read @3 (handle :UInt64) -> (subscription :ConsoleInputSubscription);
704:     # Subscribe to a session's output stream.
705:     subscribe @4 (handle :UInt64) -> (subscription :ConsoleOutputSubscription);
706:     # Detach the current focus from its session.
707:     setFocus @5 (handle :UInt64) -> (result :T.VoidResult);
708:     # Get the currently-focused session.
709:     getFocus @6 () -> (handle :UInt64);
710:     # Subscribe to multiplexer events (open/close/focus change).
711:     subscribeMultiplexer @7 () -> (subscription :ConsoleMuxSubscription);
712: }
