82: # in `metadata`, as opaque reported data. The protocol is agnostic, so it
83: # never asks — and never answers — "what kind of intelligence are you?"
84: # ══════════════════════════════════════════════════════════════════════
85: 
86: using T = import "types.capnp";
87: using import "capability.capnp".Capability;
88: 
89: # ── Identifiers ─────────────────────────────────────────────────────────
90: # Opaque references (Opacity Principle). A ModelId is not a file path, a
91: # model family, or an architecture. It is a handle.
92: 
93: struct ModelId         { id @0 :UInt64; }
94: struct RequestId       { id @0 :UInt64; }
95: struct ToolId          { id @0 :UInt64; }
96: struct AgentId         { id @0 :UInt64; }
97: struct AgentGroupId    { id @0 :UInt64; }
98: struct ConversationId  { id @0 :UInt64; }
99: struct KnowledgeBaseId { id @0 :UInt64; }
100: struct DocumentId      { id @0 :UInt64; }
101: 
102: # ── The one universal payload ────────────────────────────────────────────
103: # Carries anything: text, image, audio, video, a vector, a PDF, a symbolic
104: # term, or a format not yet invented. `mimeType` tells a consumer how to
105: # decode; an unknown subtype is ignored, not an error.
106: #
107: # This single type replaces the previous revision's Tensor,
108: # TensorShape, TensorDataType, ModelFormat, Embedding.vector,
109: # Document.content, ChatMessage.content, Query.text, HybridQuery.vectorQuery,
110: # ToolSpec.parameters/returns, ToolCall.arguments, ToolResult.result,
111: # CompletionRequest.prompt/messages and MemoryConfig.retentionPolicy.
112: #
113: # It is what makes vision, audio and PDF retrieval actually expressible:
114: # the previous revision DECLARED vision/audio/multimodal capabilities while
115: # every payload field was Text, so those models could not be called at all.
116: 
117: struct Artifact {
118:     mimeType @0 :T.MimeType;
119:     data     @1 :T.DataHandle;
120: }
121: 
122: # ── Capability discovery, as data rather than as an enum ────────────────
123: # The previous revision froze `completion, embedding, vision, audio,
124: # toolUse, structuredOutput, reasoning, multimodal` into ModelCapability.
125: # That list is today's list; a capability invented next year had nowhere to
126: # go except a new ordinal in an eternal schema.
127: #
128: # Here a capability is a NAME plus the content types it accepts and
129: # produces. A capability that does not exist yet is representable today, by
130: # construction, with no schema change — a consumer that does not recognise
131: # the name ignores it.
132: 
133: struct CapabilityDescriptor {
134:     name        @0 :Text;                 # opaque token; unknown names are ignored
135:     parent      @1 :Text;                 # open hierarchy, e.g. "input"/"output"
136:     inputTypes  @2 :List(T.MimeType);     # content types accepted
137:     outputTypes @3 :List(T.MimeType);     # content types produced
138:     parameters  @4 :T.StringMap;          # open; backend-declared keys
139: }
140: 
141: # What a model IS, reported without prescribing it.
142: # `cost` and `metadata` absorb everything the deleted enums used to say:
143: # architecture, parameter count, quantization scheme, context length,
144: # memory footprint, price, latency. All of it stays readable by consumers
145: # who care — and none of it is frozen into the contract.
146: struct ModelDescriptor {
147:     id           @0 :ModelId;
148:     name         @1 :Text;
149:     capabilities @2 :List(CapabilityDescriptor);
150:     inputTypes   @3 :List(T.MimeType);
151:     outputTypes  @4 :List(T.MimeType);
152:     resident     @5 :Bool;                # currently held in memory
153:     cost         @6 :T.StringMap;         # backend keys: memory, price, latency
154:     metadata     @7 :T.StringMap;         # backend keys: architecture, params, quantization, context
155: }
156: 
157: # ── Output negotiation ──────────────────────────────────────────────────
158: # Replaces the frozen `ResponseFormat { text, jsonObject, jsonSchema }`
159: # enum with an open content type. `schema` is itself content-typed, so a
160: # future structural-output mechanism needs no protocol change.
161: 
162: struct OutputContract {
163:     type       @0 :T.MimeType;      # what the caller wants back
164:     schema     @1 :T.DataHandle;    # optional structural constraint
165:     parameters @2 :T.StringMap;
166: }
167: 
168: # ── Metering, without presupposing a tokenizer ──────────────────────────
169: # The previous revision counted tokens (promptTokens/completionTokens/
170: # totalTokens, maxTokens, tokenCount, MemoryConfig.maxTokens). A byte-level,
171: # character-level, continuous-latent or non-generative system has no tokens,
172: # yet metering is real for all of them.
173: #
174: # The unit is a Text token. A backend reports tokens, bytes, seconds,
175: # joules, or a unit invented next year. Metering survives; the tokenizer
176: # assumption does not.
177: 
178: struct Usage {
179:     quantity   @0 :Float64;
180:     unit       @1 :Text;             # open: "token", "byte", "second", ...
181:     dimensions @2 :T.StringMap;      # e.g. {"input": "12", "output": "30"}
182: }
183: 
184: # ── Execution mode, as a union rather than a second API ─────────────────
185: # Streaming is an ALTERNATIVE MODE of one operation, not a parallel API.
186: # That matters: the previous revision's CompletionStream returned a
187: # ChatMessage delta per pull, which only an autoregressive token model can
188: # produce. A masked diffusion model fills a whole sequence in parallel and
189: # has no delta, no token index and no causal order — it was declared
190: # (`ModelArchitecture.diffusion`) and simultaneously unusable.
191: #
192: # As a mode, a whole-sequence model simply returns its complete output as
193: # one Artifact. No field anywhere in this file assumes incremental tokens.
194: 
195: struct ExecutionMode {
196:     union {
197:         complete @0 :Void;
198:         stream   @1 :Void;
199:         # Forward compatibility: a mode added after this schema was frozen
200:         # arrives here rather than silently defaulting to `complete`.
201:         unknown  @2 :Void;
202:     }
203: }
204: 
205: # ── A piece of input ────────────────────────────────────────────────────
206: # Replaces the frozen MessageRole enum (system/user/assistant/tool/
207: # developer), which was one vendor's 2023 chat API — `developer` was
208: # already a renamed role upstream.
209: #
210: # `contributor` is an open token. That yields three things from one
211: # construct: multimodal input (a list of differently-typed Artifacts),
212: # multi-agent exchange (an agent is just another contributor, so no
213: # separate agent-message protocol is needed), and today's chat roles as
214: # ordinary conventions.
215: 
216: struct Part {
217:     artifact    @0 :Artifact;
218:     contributor @1 :Text;             # "system", "user", "agent", a tool name, ...
219:     annotations @2 :T.StringMap;
220:     replyTo     @3 :RequestId;        # non-zero when this is a tool result
221: }
222: 
223: struct InferenceRequest {
224:     request    @0 :RequestId;         # caller-chosen identity: retry/dedupe is idempotent
225:     model      @1 :ModelId;
226:     inputs     @2 :List(Part);
227:     output     @3 :OutputContract;
228:     mode       @4 :ExecutionMode;
229:     parameters @5 :T.StringMap;       # open: sampling knobs, tool selection, stop conditions
230:     budget     @6 :T.Duration;        # caller's time budget
231: }
232: # `parameters` deliberately replaces the frozen OpenAI-shaped fields
233: # maxTokens / temperature / topP / topK / stopSequences / presencePenalty /
234: # frequencyPenalty / logitBias / seed / toolChoice / responseFormat. Two
235: # reasons they cannot be fields: they presuppose logits and a tokenizer, so
236: # an energy-based, diffusion or retrieval-only backend must fill them with
237: # lies; and as published ordinals they could never be removed
238: # (TIMELESSNESS.md:96) even after they became meaningless. As open keys they
239: # cost nothing when absent and never need an ordinal.
240: 
241: struct InferenceResponse {
242:     request  @0 :RequestId;
243:     model    @1 :ModelId;
244:     outputs  @2 :List(Artifact);
245:     usage    @3 :Usage;
246:     warnings @4 :List(T.Warning);     # non-fatal degradation
247:     custom   @5 :Data;
248: }
249: 
250: # ── Streams ─────────────────────────────────────────────────────────────
251: # A STRUCTURAL terminator. Every chunked stream elsewhere in this protocol
252: # returns `done :Bool` (web.capnp, speech.capnp, system_search.capnp,
253: # archive.capnp); the previous ai.capnp returned neither, leaving clients to
254: # infer termination from a nested finishReason hint.
255: 
256: struct StreamStatus {
257:     union {
258:         more      @0 :Void;
259:         complete  @1 :Void;
260:         failed    @2 :T.Error;
261:         cancelled @3 :Void;
262:         unknown   @4 :Void;
263:     }
264: }
265: 
266: struct StreamFrame {
267:     request  @0 :RequestId;
268:     artifact @1 :Artifact;
269:     status   @2 :StreamStatus;
270:     sequence @3 :UInt64;              # monotonic; detects dropped frames
271:     custom   @4 :Data;
272: }
273: 
274: interface ArtifactStream {
275:     # maxBytes is caller-driven backpressure: the producer may never send
276:     # faster than the consumer pulls.
277:     pull  @0 (maxBytes :UInt32) -> (frame :StreamFrame);
278:     cancel @1 () -> T.VoidResult;
279: }
280: 
281: # ── Models ──────────────────────────────────────────────────────────────
282: # A model arrives as CONTENT, so no serialization format is frozen. The
283: # deleted ModelFormat enum named onnx / safetensors / gguf; q4km, q4_0,
284: # q5_0 and q8_0 in TensorDataType are GGUF FILENAME TOKENS, not concepts.
285: 
286: struct ModelFilter {
287:     namePattern @0 :Text;
288:     capability  @1 :Text;             # open token, matches CapabilityDescriptor.name
289:     resident    @2 :T.BoolFilter;     # any / yes / no
290:     annotations @3 :T.StringMap;
291: }
292: 
293: interface ModelService {
294:     # Holding this reference IS the authority to load and unload.
295:     load     @0 (declaration :Artifact, annotations :T.StringMap) -> (model :ModelId);
296:     unload   @1 (model :ModelId) -> T.VoidResult;
297:     release  @2 (model :ModelId) -> T.VoidResult;
298:     describe @3 (model :ModelId) -> (descriptor :ModelDescriptor);
299:     list     @4 (filter :ModelFilter, page :T.Pagination)
300:             -> (models :List(ModelDescriptor), total :UInt64);
301: }
302: 
303: # ── Inference ───────────────────────────────────────────────────────────
304: # ONE method for every single-shot transform. Completion, embedding,
305: # classification, reranking, reward scoring and moderation are all
306: # `derive` differing only in output contract — so there is no
307: # embedding-specific API, and no per-task API to outgrow as tasks appear.
308: #
309: # The previous revision's README advertised InferenceService.complete(),
310: # which existed in no schema, while CompletionRequest, CompletionResponse,
311: # EmbedRequest, EmbedResponse, ModelSpec and ModelInfo were orphans
312: # referenced by no method at all.
313: 
314: interface InferenceService {
315:     derive     @0 (request :InferenceRequest) -> (response :InferenceResponse);
316:     openStream @1 (request :InferenceRequest) -> (stream :ArtifactStream);
317:     cancel     @2 (request :RequestId) -> T.VoidResult;
318: }
319: 
320: # ── Tools ───────────────────────────────────────────────────────────────
321: # A tool declaration is content, so tool schemas are not frozen to JSON
322: # Schema: JSON Schema today, anything declarative tomorrow.
323: #
324: # invoke() carries no authority parameter because holding this reference IS
325: # the authority. The previous revision's ToolRegistry.invoke took no
326: # authority of any kind — unauthenticated remote code execution — while the
327: # file's own header claimed all privileged operations were capability-gated.
328: 
329: struct ToolDeclaration {
330:     name        @0 :Text;
331:     description @1 :Text;
332:     parameters  @2 :Artifact;
333:     result      @3 :Artifact;
334:     annotations @4 :T.StringMap;
335: }
336: 
337: struct ToolInvocation {
338:     request     @0 :RequestId;
339:     tool        @1 :ToolId;
340:     arguments   @2 :Artifact;
341:     annotations @3 :T.StringMap;
342: }
343: 
344: # A union, not parallel fields: `success = false` with a nil `error` used
345: # to be representable, leaving a consumer with a failure and no cause.
346: # The same file gets this right everywhere else (StreamStatus, AIEvent);
347: # this was the one place a failure could be swallowed.
348: struct ToolOutcome {
349:     request @0 :RequestId;
350:     union {
351:         success @1 :ToolOutcomeSuccess;
352:         unknown @2 :T.UnknownEvent;
353:         error   @3 :T.Error;
354:     }
355:     custom  @4 :Data;
356: }
357: 
358: struct ToolOutcomeSuccess {
359:     result @0 :Artifact;
360:     custom @1 :Data;
361: }
362: 
363: interface ToolRegistry {
364:     register   @0 (tool :Artifact, declaration :ToolDeclaration) -> (tool :ToolId);
365:     unregister @1 (tool :ToolId) -> T.VoidResult;
366:     get        @2 (tool :ToolId) -> (declaration :ToolDeclaration);
367:     list       @3 (page :T.Pagination) -> (tools :List(ToolDeclaration), total :UInt64);
368:     invoke     @4 (invocation :ToolInvocation) -> (outcome :ToolOutcome);
369: }
370: 
371: # ── Agents ──────────────────────────────────────────────────────────────
372: # No role enum, no MemoryType taxonomy (conversation/semantic/episodic/
373: # hybrid — a library's internal memory classes, not a wire contract), no
374: # ChunkingType, no SwarmTopology (star/mesh/ring/hierarchical are scheduler
375: # internals; TIMELESSNESS.md:84 rejects scheduler hints from the protocol).
376: 
377: struct AgentDeclaration {
378:     name         @0 :Text;
379:     description  @1 :Text;
380:     model        @2 :ModelId;
381:     declaration  @3 :Artifact;        # the agent's own contract/manifest
382:     instructions @4 :Artifact;        # content, not a text systemPrompt:
383:                                       # may carry images, audio, retrieved evidence
384:     memory       @5 :Artifact;        # memory described by content type,
385:                                       # implemented however the backend likes
386:     annotations  @6 :T.StringMap;
387: }
388: 
389: struct AgentDescriptor {
390:     id                @0 :AgentId;
391:     declaration       @1 :AgentDeclaration;
392:     grantedAuthority  @2 :List(Capability);  # reported, not checked here
393:     status            @3 :Text;        # opaque token; unknown values ignored
394:     state             @4 :T.StringMap;
395: }
396: 
397: struct AgentMessage {
398:     request     @0 :RequestId;
399:     from        @1 :Text;             # agent name/id, or any participant
400:     to          @2 :Text;
401:     content     @3 :Artifact;
402:     annotations @4 :T.StringMap;
403:     replyTo     @5 :RequestId;
404: }
405: 
406: # A refused, crashed or unfilled agent turn is representable on the wire.
407: # Returning a bare AgentMessage forced every consumer to ask "did this
408: # fail, or did the agent say nothing?" of an empty replyTo/artifact.
409: struct AgentSendResult {
410:     union {
411:         reply   @0 :AgentMessage;
412:         error   @1 :T.Error;
413:         unknown @2 :T.UnknownEvent;
414:     }
415: }
416: 
417: struct AgentGroupSpec {
418:     name        @0 :Text;
419:     members     @1 :List(AgentId);
420:     coordinator @2 :Text;             # open; may be absent for emergent groups
421:     topology    @3 :T.StringMap;      # open map, not a frozen enum
422: }
423: 
424: struct AgentFilter {
425:     namePattern @0 :Text;
426:     group       @1 :AgentGroupId;
427:     status      @2 :Text;
428:     model       @3 :ModelId;
429:     annotations @4 :T.StringMap;
430: }
431: 
432: interface AgentService {
433:     spawn      @0 (agent :AgentDeclaration) -> (agent :AgentId);
434:     terminate  @1 (agent :AgentId, graceful :Bool) -> T.VoidResult;
435:     send       @2 (message :AgentMessage) -> (result :AgentSendResult);
436:     describe   @3 (agent :AgentId) -> (descriptor :AgentDescriptor);
437:     list       @4 (filter :AgentFilter, page :T.Pagination)
438:              -> (agents :List(AgentDescriptor), total :UInt64);
439:     createGroup @5 (group :AgentGroupSpec) -> (group :AgentGroupId);
440:     broadcast  @6 (group :AgentGroupId, message :AgentMessage) -> T.VoidResult;
441:     getGroup   @7 (group :AgentGroupId) -> (group :AgentGroupSpec);
442: }
443: 
444: # ── Knowledge ───────────────────────────────────────────────────────────
445: # Documents are LISTS OF ARTIFACTS, so retrieval covers PDFs, images, audio
446: # and video — not just text, as the previous revision's
447: # `Document.content :Text` made it.
448: #
449: # Queries are artifacts too: text, an image (visual search), a vector, audio
450: # or anything future.
451: #
452: # query() returns DocumentRef, not Document. The previous revision returned
453: # the entire Document — including its full List(Float32) embedding — for
454: # every hit, so topK=100 shipped 100 documents plus 100 copied vectors where
455: # the caller needed short passages. `evidence` carries the snippet;
456: # `KnowledgeBaseService.get` fetches a full document on demand.
457: 
458: struct Document {
459:     id          @0 :DocumentId;
460:     content     @1 :List(Artifact);
461:     annotations @2 :T.StringMap;
462: }
463: 
464: struct DocumentRef {
465:     id          @0 :DocumentId;
466:     annotations @1 :T.StringMap;
467: }
468: 
469: struct RetrievalQuery {
470:     query           @0 :Artifact;
471:     topK            @1 :UInt32;
472:     annotations     @2 :T.StringMap;
473:     scoreThreshold  @3 :Float32;
474: }
475: 
476: struct RetrievalHit {
477:     document    @0 :DocumentRef;
478:     score       @1 :Float32;
479:     rank        @2 :UInt32;
480:     evidence    @3 :Artifact;        # optional snippet
481:     annotations @4 :T.StringMap;
482: }
483: 
484: interface KnowledgeBaseService {
485:     # `configuration` absorbs index type, chunking strategy and distance
486:     # metric: backend configuration, not protocol.
487:     #
488:     # No embedding model is REQUIRED, because retrieval here is not
489:     # necessarily vector retrieval. An inverted index, a lexical ranker, a
490:     # graph walk, a SQL view, a symbolic triple store and a dense vector
491:     # store are all the same call. Requiring an embedding model would bake
492:     # today's dominant retrieval technique into an eternal contract — the
493:     # same error as freezing an architecture enum. Any model a backend uses
494:     # internally is named in `configuration`, and its capabilities are
495:     # discoverable through AI.discover.
496:     create      @0 (name :Text, configuration :T.StringMap)
497:                -> (base :KnowledgeBaseId);
498:     delete      @1 (base :KnowledgeBaseId) -> T.VoidResult;
499:     add         @2 (base :KnowledgeBaseId, documents :List(Document)) -> (ids :List(DocumentId));
500:     remove      @3 (base :KnowledgeBaseId, ids :List(DocumentId)) -> T.VoidResult;
501:     get         @4 (base :KnowledgeBaseId, id :DocumentId) -> (document :Document);
502:     query       @5 (base :KnowledgeBaseId, query :RetrievalQuery) -> (hits :List(RetrievalHit));
503:     queryStream @6 (base :KnowledgeBaseId, query :RetrievalQuery) -> (stream :ArtifactStream);
504: }
505: 
506: # ── Conversations ───────────────────────────────────────────────────────
507: # `context` is an Artifact, not a Text systemPrompt — a conversation can be
508: # grounded in images, audio or retrieved evidence.
509: 
510: struct ConversationSpec {
511:     model        @0 :ModelId;
512:     tools        @1 :List(ToolId);
513:     context      @2 :Artifact;
514:     configuration @3 :T.StringMap;   # compression strategy and the like, as open keys
515: }
516: 
517: struct Conversation {
518:     id          @0 :ConversationId;
519:     spec        @1 :ConversationSpec;
520:     messages    @2 :List(Part);
521:     created     @3 :T.Timestamp;
522:     updated     @4 :T.Timestamp;
523:     usage       @5 :Usage;
524:     annotations @6 :T.StringMap;
525: }
526: 
527: struct ConversationFilter {
528:     model        @0 :ModelId;
529:     since        @1 :T.Timestamp;
530:     annotations  @2 :T.StringMap;
531: }
532: 
533: interface ConversationService {
534:     create @0 (spec :ConversationSpec) -> (conversation :ConversationId);
535:     # Paginated: the previous revision's get returned unbounded history.
536:     get    @1 (conversation :ConversationId, page :T.Pagination)
537:          -> (conversation :Conversation, total :UInt64);
538:     append @2 (conversation :ConversationId, parts :List(Part)) -> (request :RequestId);
539:     fork   @3 (conversation :ConversationId, fromIndex :UInt32) -> (conversation :ConversationId);
540:     delete @4 (conversation :ConversationId) -> T.VoidResult;
541:     list   @5 (filter :ConversationFilter, page :T.Pagination)
542:          -> (conversations :List(Conversation), total :UInt64);
543: }
544: 
545: # ── Events ──────────────────────────────────────────────────────────────
546: # Content-typed, so no event type can ever need adding: a lifecycle event
547: # for a request, model, agent, conversation or knowledge base is an Artifact
548: # whose mimeType names it. The previous revision froze ModelEventType,
549: # AgentEventType and ConversationEventType — three enums, none of which had
550: # a custom variant, so a backend adding one had nowhere to go.
551: #
552: # at is monotonic, so ordering survives clock adjustment. sequence supports
553: # dedup and gap detection.
554: 
555: struct AIEvent {
556:     union {
557:         request       @0 :Artifact;
558:         model         @1 :Artifact;
559:         agent         @2 :Artifact;
560:         conversation  @3 :Artifact;
561:         knowledge     @4 :Artifact;
562:         notice        @5 :T.Warning;
563:         unknown       @6 :T.UnknownEvent;
564:     }
565:     at       @7 :T.MonotonicTimestamp;
566:     sequence @8 :UInt64;
567: }
568: 
569: interface AISubscription {
570:     # maxEvents is caller-driven backpressure, the same discipline
571:     # ArtifactStream.pull @0 (maxBytes :UInt32) applies to byte streams:
572:     # the producer may never push faster than the consumer pulls. The
573:     # caller controls the bound; zero means "one event" so a consumer
574:     # cannot accidentally ask for an unbounded batch by leaving it unset.
575:     pull  @0 (maxEvents :UInt32) -> (events :List(AIEvent));
576:     cancel @1 () -> T.VoidResult;
577: }
578: 
579: # ── Entry point ─────────────────────────────────────────────────────────
580: # ONE root, so every interface above is reachable — the previous revision
581: # declared six interfaces and not one method in the entire protocol returned
582: # any of them, so nothing in it could actually be called.
583: #
584: # Returning interfaces matches speech.capnp (AudioStream) and web.capnp
585: # (HttpStream).
586: #
587: # Authority is gated HERE, at acquisition, and nowhere else. Only handshake
588: # and discover are ungated, so capability discovery is open to everyone
589: # while every resource-consuming or state-mutating operation requires a
590: # reference that was granted. handshake publishes known models so that
591: # discovery is possible before any capability is held — otherwise
592: # acquire-to-discover would deadlock.
593: 
594: interface AI {
595:     handshake     @0 () -> (info :T.Version,
596:                             contentTypes :List(T.MimeType),
597:                             models :List(ModelDescriptor));
598:     discover      @1 (model :ModelId) -> (descriptor :ModelDescriptor);
599: 
600:     models        @2 (authority :Capability) -> (service :ModelService);
601:     inference     @3 (authority :Capability) -> (service :InferenceService);
602:     tools         @4 (authority :Capability) -> (service :ToolRegistry);
603:     agents        @5 (authority :Capability) -> (service :AgentService);
604:     knowledge     @6 (authority :Capability) -> (service :KnowledgeBaseService);
605:     conversations @7 (authority :Capability) -> (service :ConversationService);
606:     subscribe     @8 (authority :Capability, filter :T.StringMap) -> (subscription :AISubscription);
607: }
608: 
609: # ══════════════════════════════════════════════════════════════════════
610: # CONFORMANCE TOKENS — conventions, NOT contract
611: #
612: # Nothing above depends on any declaration in this section. They are
613: # published so that today's tools have a discoverable spelling, not so that
614: # the protocol can require one. This section can therefore grow without
615: # touching a single ordinal, and an unrecognized value MUST be ignored
616: # rather than rejected.
617: #
618: # They are Text and T.MimeType values, deliberately NOT enums: an enum here
619: # would be an eternal commitment to today's spelling of a concept.
620: # ══════════════════════════════════════════════════════════════════════
621: 
622: const textContent   :T.MimeType = (type = "text",        subtype = "plain");
623: const jsonContent   :T.MimeType = (type = "application", subtype = "json");
624: const binaryContent :T.MimeType = (type = "application", subtype = "octet-stream");
625: 
626: # A dense vector is content, not a List(Float32) in the schema. The subtype
627: # is a convention; parameters carry dimensionality, e.g. {"dimensions":"4096"}.
628: const embeddingContent :T.MimeType = (type = "application", subtype = "vnd.smart.embedding");
629: 
630: # Tool parameter schemas. Any declarative format is equally valid — a
631: # protocol that required JSON Schema would be frozen against its successor.
632: const jsonSchemaContent :T.MimeType = (type = "application", subtype = "schema+json");
