58:         if w <= 0.0 {
59:             return String::new();
60:         }
61:         if self.tw(p, s, f) <= w {
62:             return s.to_string();
63:         }
64:         let chars: Vec<char> = s.chars().collect();
65:         let (mut lo, mut hi) = (0usize, chars.len());
66:         while lo < hi {
