69:             if self.tw(p, &t, f) <= w {
70:                 lo = mid
71:             } else {
72:                 hi = mid - 1
73:             }
74:         }
75:         chars[..lo].iter().collect::<String>().trim_end().to_string() + "\u{2026}"
