354:             let ctr = origin + vec2(6.0 + 20.0 * i as f32, 0.0);
355:             let rect = Rect::from_center_size(ctr, vec2(16.0, 16.0));
356:             let resp = self.hit(ui, rect, (id, n), Sense::click());
357:             let s = if resp.hovered() { 1.14 } else { 1.0 };
358:             let dot = Rect::from_center_size(ctr, vec2(12.0 * s, 12.0 * s));
359:             shadow(p, dot, 6.0, 0.5, 1.0, 0.0, c(20, 29, 48, 0.12));
360:             let (a, b) = if resp.is_pointer_button_down_on() { (mix(*a, Color32::BLACK, 0.12), mix(*b, Color32::BLACK, 0.12)) } else { (*a, *b) };
361:             grad_fill(p, dot, 6.0 * s, a, b);
362:             rim(p, dot, 6.0, 1.0, Color32::from_white_alpha(95), true, 7.0);
363:             if g_hover {
364:                 let k = c(40, 20, 18, 0.55);
365:                 let st = egui::Stroke::new(1.35, k);
366:                 match *n {
367:                     "close" => {
368:                         p.line_segment([ctr + vec2(-2.8, -2.8), ctr + vec2(2.8, 2.8)], st);
369:                         p.line_segment([ctr + vec2(2.8, -2.8), ctr + vec2(-2.8, 2.8)], st);
370:                     }
371:                     "min" => {
372:                         p.line_segment([ctr + vec2(-3.0, 0.0), ctr + vec2(3.0, 0.0)], st);
373:                     }
374:                     _ => {
375:                         p.line_segment([ctr + vec2(-2.6, 2.6), ctr + vec2(2.6, -2.6)], st);
376:                         p.line_segment([ctr + vec2(2.6, -2.6), ctr + vec2(0.4, -2.6)], st);
377:                         p.line_segment([ctr + vec2(2.6, -2.6), ctr + vec2(2.6, -0.4)], st);
378:                     }
379:                 }
380:             }
381:             if resp.clicked() {
382:                 self.push_act(match *n {
383:                     "close" => Act::WinClose,
384:                     "min" => Act::WinMin,
385:                     _ => Act::WinZoom,
386:                 });
387:             }
388:         }
389:     }
