463:     fn tree_children(&mut self, loc: &Location, now: f64) -> Vec<Location> {
464:         if let Some((t, v)) = self.tree_cache.get(loc) {
465:             if now - *t < 3.0 {
466:                 return v.clone();
467:             }
468:         }
469:         let v = self
470:             .be
471:             .registry
472:             .get(&loc.fs)
473:             .and_then(|fs| fs.list(&loc.path).ok())
474:             .map(|l| {
475:                 let mut d: Vec<Entry> = l.into_iter().filter(|e| e.is_dir && !e.hidden).collect();
476:                 d.sort_by(|a, b| natural_cmp(&a.name, &b.name));
477:                 d.into_iter().map(|e| e.loc).collect::<Vec<_>>()
478:             })
479:             .unwrap_or_default();
480:         self.tree_cache.insert(loc.clone(), (now, v.clone()));
481:         v
482:     }
