484:     /// Flattened, depth-first view of the expanded folder tree rooted at Home.
485:     fn tree_flat(&mut self, now: f64) -> Vec<(Location, usize, String, bool, bool)> {
486:         let root = self.be.home();
487:         if !self.tree_init {
488:             self.tree_init = true;
489:             self.tree_open.insert(root.clone());
490:         }
491:         let mut out = vec![];
492:         let mut stack = vec![(root, 0usize)];
493:         while let Some((loc, depth)) = stack.pop() {
494:             let kids = self.tree_children(&loc, now);
495:             let open = self.tree_open.contains(&loc);
496:             let name = if depth == 0 { "Home".to_string() } else { loc.name() };
497:             out.push((loc.clone(), depth, name, !kids.is_empty(), open));
498:             if open && depth < 6 && out.len() < 300 {
499:                 for k in kids.iter().rev() {
500:                     stack.push((k.clone(), depth + 1));
501:                 }
502:             }
503:         }
504:         out
505:     }
