517:             }
518:         };
519:         let base = nav.top() + dy;
520:         // ── Favorites
521:         label(y, "Favorites", None);
522:         y += 22.0;
523:         let mut rows: Vec<(String, &'static str, Route, Option<usize>, Option<Location>)> = vec![];
524:         let places = self.places.clone();
525:         for pl in &places {
526:             rows.push((pl.title.clone(), pl.icon, Route::Loc(pl.loc.clone()), self.place_counts.get(&pl.loc).copied(), Some(pl.loc.clone())));
527:             if pl.id == "home" {
528:                 rows.push(("Recents".into(), "clock-circle", Route::Recents, None, None));
529:             }
530:         }
531:         for pin in self.lib(|l| l.pins.clone()) {
532:             rows.insert(1, (pin.name(), "folder", Route::Loc(pin.clone()), None, Some(pin)));
533:         }
534:         for (name, icon, route, count, loc) in rows {
535:             let rect = Rect::from_min_size(pos2(x0, y), vec2(w, 32.0));
536:             let active = cur == route;
537:             let visible = rect.bottom() > nav.top() - 4.0 && rect.top() < nav.bottom() + 4.0;
538:             let dropping = self.drag.is_some() && visible && ui.rect_contains_pointer(rect);
539:             if visible {
540:                 if let Some(l) = &loc {
541:                     DROP_TARGETS.with(|v| v.borrow_mut().push((DropTarget::Place(l.clone()), rect)));
542:                 }
543:                 self.sb_row(ui, rect, icon, &name, active, count.map(|c| c.to_string()), dropping, &format!("place-{}", name));
544:             }
545:             if visible {
546:                 let r = self.hit(ui, rect, ("sbrow", format!("place-{}", name)), Sense::click());
547:                 if r.clicked() {
548:                     self.push_act(Act::Nav(route.clone()));
549:                 }
550:                 if r.secondary_clicked() {
551:                     if let Some(l) = loc.clone() {
552:                         self.menu = Some(Menu { kind: MenuKind::Place, pos: ui.ctx().pointer_latest_pos().unwrap_or(rect.center()), target: Some(l), device: None, sub: None, age: 0.0 });
553:                     }
554:                 }
555:             }
556:             y += 33.0;
557:         }
558:         // ── Locations
559:         y += 14.0;
560:         label(y, "Locations", None);
561:         y += 23.0;
562:         for d in self.devices.clone() {
563:             let rect = Rect::from_min_size(pos2(x0, y), vec2(w, 32.0));
564:             let active = matches!(&cur, Route::Loc(l) if d.loc.as_ref().is_some_and(|dl| l == dl || (d.kind != DeviceKind::Internal && l.fs == dl.fs && l.starts_with(dl))));
565:             let visible = rect.bottom() > nav.top() - 4.0 && rect.top() < nav.bottom() + 4.0;
566:             let dropping = self.drag.is_some() && visible && d.mounted && ui.rect_contains_pointer(rect);
567:             if visible {
568:                 if let (Some(l), true) = (&d.loc, d.mounted) {
569:                     DROP_TARGETS.with(|v| v.borrow_mut().push((DropTarget::Place(l.clone()), rect)));
570:                 }
571:                 self.sb_row_device(ui, rect, &d, active, dropping);
572:                 let r = self.hit(ui, rect, ("dev", &d.id), Sense::click());
573:                 if r.clicked() {
574:                     match (&d.loc, d.mounted, d.kind) {
575:                         (_, _, DeviceKind::Phone) => self.push_act(Act::Modal(Modal::Phone)),
576:                         (Some(l), true, _) => self.push_act(Act::Nav(Route::Loc(l.clone()))),
577:                         _ => self.push_act(Act::Mount(d.id.clone())),
578:                     }
579:                 }
580:                 if r.secondary_clicked() {
581:                     self.menu = Some(Menu { kind: MenuKind::Device, pos: ui.ctx().pointer_latest_pos().unwrap_or(rect.center()), target: d.loc.clone(), device: Some(d.id.clone()), sub: None, age: 0.0 });
582:                 }
583:             }
584:             y += 33.0;
585:         }
586:         {
587:             let rect = Rect::from_min_size(pos2(x0, y), vec2(w, 32.0));
588:             let visible = rect.bottom() > nav.top() - 4.0 && rect.top() < nav.bottom() + 4.0;
589:             if visible {
590:                 if self.sb_row(ui, rect, "add", "Mount a device\u{2026}", false, None, false, "mount-dev").clicked() {
591:                     self.push_act(Act::Modal(Modal::Devices));
592:                 }
593:             }
594:             y += 33.0;
595:         }
596:         {
597:             let rect = Rect::from_min_size(pos2(x0, y), vec2(w, 32.0));
598:             let visible = rect.bottom() > nav.top() - 4.0 && rect.top() < nav.bottom() + 4.0;
599:             if visible {
600:                 let active = cur == Route::Trash;
601:                 if self.sb_row(ui, rect, "trash-bin-trash", "Trash", active, None, false, "trash").clicked() {
602:                     self.push_act(Act::Nav(Route::Trash));
603:                 }
604:                 let r = self.hit(ui, rect, ("sb-trash-menu",), Sense::click());
605:                 if r.secondary_clicked() {
606:                     self.push_act(Act::Nav(Route::Trash));
607:                     self.menu = Some(Menu { kind: MenuKind::Background, pos: ui.ctx().pointer_latest_pos().unwrap_or(rect.center()), target: None, device: None, sub: None, age: 0.0 });
608:                 }
609:             }
610:             y += 33.0;
611:         }
612:         // ── Folder tree
613:         y += 14.0;
614:         label(y, "Folders", None);
615:         y += 23.0;
616:         let now = self.time;
617:         let flat = self.tree_flat(now);
618:         for (loc, depth, name, has_kids, open) in flat {
619:             let rect = Rect::from_min_size(pos2(x0, y), vec2(w, 28.0));
620:             let visible = rect.bottom() > nav.top() - 4.0 && rect.top() < nav.bottom() + 4.0;
621:             if visible {
622:                 let active = cur == Route::Loc(loc.clone());
623:                 let dropping = self.drag.is_some() && ui.rect_contains_pointer(rect);
624:                 DROP_TARGETS.with(|v| v.borrow_mut().push((DropTarget::Place(loc.clone()), rect)));
625:                 let r = self.hit(ui, rect, ("tree", &loc), Sense::click());
626:                 if active || dropping {
627:                     p.rect_filled(rect, cr(10.0), th.accent_tint);
628:                 } else if r.is_pointer_button_down_on() {
629:                     p.rect_filled(rect, cr(10.0), th.row_press);
630:                 } else if r.hovered() {
631:                     p.rect_filled(rect, cr(10.0), th.row_hover);
632:                 }
633:                 let ind = 6.0 + depth as f32 * 14.0;
634:                 if has_kids {
635:                     let cb = Rect::from_center_size(pos2(rect.left() + ind + 9.0, rect.center().y), vec2(20.0, 20.0));
636:                     let cresp = self.hit(ui, cb, ("treechev", &loc), Sense::click());
637:                     let t = spring_to(ui.ctx(), ("tree-rot", &loc), if open { 1.0 } else { 0.0 }, 320.0, 24.0);
638:                     if cresp.hovered() {
639:                         p.circle_filled(cb.center(), 9.0, th.row_press);
640:                     }
641:                     let ang = t * std::f32::consts::FRAC_PI_2;
642:                     let rot = |v: egui::Vec2| vec2(v.x * ang.cos() - v.y * ang.sin(), v.x * ang.sin() + v.y * ang.cos());
643:                     let s = egui::Stroke::new(1.6, if cresp.hovered() { th.ink2 } else { th.ink4 });
644:                     let (a0, a1, a2) = (rot(vec2(-1.5, -3.5)), rot(vec2(2.0, 0.0)), rot(vec2(-1.5, 3.5)));
645:                     p.line_segment([cb.center() + a0, cb.center() + a1], s);
646:                     p.line_segment([cb.center() + a1, cb.center() + a2], s);
647:                     if cresp.clicked() {
648:                         if !self.tree_open.remove(&loc) {
649:                             self.tree_open.insert(loc.clone());
650:                         }
651:                     }
652:                 }
653:                 let ix = rect.left() + ind + 30.0;
654:                 self.ico(p, if open || active { "folder-open" } else { "folder" }, if active { Ic::Filled } else { Ic::Duo }, pos2(ix, rect.center().y), 15.0, if active { th.accent_ink } else { th.ink3 });
655:                 let f = if active { f_semi(T_BODY) } else { f_medium(T_BODY) };
656:                 p.text(pos2(ix + 15.0, rect.center().y), Align2::LEFT_CENTER, self.fit(p, &name, &f, (rect.right() - ix - 22.0).max(20.0)), f, if active { th.accent_ink } else { th.ink2 });
657:                 if r.clicked() {
658:                     self.push_act(Act::Nav(Route::Loc(loc.clone())));
659:                     if has_kids && !open {
660:                         self.tree_open.insert(loc.clone());
661:                     }
662:                 }
663:                 if r.secondary_clicked() {
664:                     self.menu = Some(Menu { kind: MenuKind::Place, pos: ui.ctx().pointer_latest_pos().unwrap_or(rect.center()), target: Some(loc.clone()), device: None, sub: None, age: 0.0 });
665:                 }
666:             }
667:             y += 29.0;
668:         }
669:         // ── Tags
670:         y += 14.0;
671:         let tags = self.lib(|l| l.tags.clone());
672:         label(y, "Tags", None);
673:         y += 23.0;
674:         for t in tags {
675:             let rect = Rect::from_min_size(pos2(x0, y), vec2(w, 32.0));
676:             let active = cur == Route::Tag(t.id.clone());
677:             let n = self.lib(|l| l.tag_count(&t.id));
678:             let visible = rect.bottom() > nav.top() - 4.0 && rect.top() < nav.bottom() + 4.0;
679:             let dropping = self.drag.is_some() && visible && ui.rect_contains_pointer(rect);
680:             if visible {
681:                 DROP_TARGETS.with(|v| v.borrow_mut().push((DropTarget::Tag(t.id.clone()), rect)));
682:                 let r = self.sb_row_tag(ui, rect, &t.name, hex(&t.color), active, n, dropping);
683:                 if r.clicked() {
684:                     self.push_act(Act::Nav(Route::Tag(t.id.clone())));
685:                 }
686:             }
687:             y += 33.0;
688:         }
689:         {
690:             let rect = Rect::from_min_size(pos2(x0, y), vec2(w, 32.0));
691:             let visible = rect.bottom() > nav.top() - 4.0 && rect.top() < nav.bottom() + 4.0;
692:             if visible && self.sb_row(ui, rect, "add", "New tag\u{2026}", false, None, false, "new-tag").clicked() {
693:                 self.push_act(Act::Modal(Modal::NewTag));
694:             }
695:             y += 33.0;
696:         }
697:         y += 12.0;
698:         // store content height for the scroll clamp
