704:     pub(crate) fn sb_row(&self, ui: &Ui, rect: Rect, icon: &'static str, name: &str, active: bool, tail: Option<String>, drop: bool, id: &str) -> Response {
705:         let r = self.hit(ui, rect, ("sbrow", id), Sense::click());
706:         let p = ui.painter();
707:         let th = &self.th;
708:         if active || drop {
709:             p.rect_filled(rect, cr(10.0), th.accent_tint);
710:             if drop && !active {
711:                 p.rect_stroke(rect.shrink(0.5), cr(10.0), egui::Stroke::new(1.5, alpha(th.accent, 0.6)), egui::StrokeKind::Inside);
712:             }
713:         } else if r.is_pointer_button_down_on() {
714:             p.rect_filled(rect, cr(10.0), th.row_press);
715:         } else if r.hovered() {
716:             p.rect_filled(rect, cr(10.0), th.row_hover);
717:         }
718:         let col = if active { th.accent_ink } else { th.ink2 };
719:         self.ico(p, icon, if active { Ic::Filled } else { Ic::Duo }, pos2(rect.left() + 19.0, rect.center().y), 16.0, if active { th.accent_ink } else { th.ink3 });
720:         let f = if active { f_semi(T_BODY) } else { f_medium(T_BODY) };
721:         let max = rect.width() - 58.0;
722:         let label = self.fit(p, name, &f, max);
723:         p.text(pos2(rect.left() + 37.0, rect.center().y), Align2::LEFT_CENTER, label, f, col);
724:         if let Some(t) = tail {
725:             p.text(pos2(rect.right() - 12.0, rect.center().y), Align2::RIGHT_CENTER, t, f_medium(T_META), if active { alpha(th.accent_ink, 0.9) } else { th.ink4 });
726:         }
727:         r
728:     }
