730:     fn sb_row_tag(&self, ui: &Ui, rect: Rect, name: &str, color: Color32, active: bool, n: usize, drop: bool) -> Response {
731:         let r = self.hit(ui, rect, ("tag", name), Sense::click());
732:         let p = ui.painter();
733:         let th = &self.th;
734:         if active || drop {
735:             p.rect_filled(rect, cr(10.0), th.accent_tint);
736:             if drop && !active {
737:                 p.rect_stroke(rect.shrink(0.5), cr(10.0), egui::Stroke::new(1.5, alpha(th.accent, 0.6)), egui::StrokeKind::Inside);
738:             }
739:         } else if r.hovered() {
740:             p.rect_filled(rect, cr(10.0), th.row_hover);
741:         }
