369:             1 => self.storage_cleanup(ui, &p, body, &mut st, &sn),
370:             2 => self.storage_map(ui, &p, body, &mut st),
371:             3 => self.storage_graph(ui, &p, body, &mut st),
372:             _ => self.storage_biggest(ui, &p, body, &mut st, &sn),
373:         }
374:         st.snap = Some(sn);
375:         self.storage = Some(st);
376:     }
