384:         let warn = used >= 0.90;
385:         let ico = Rect::from_min_size(r.min + vec2(16.0, 16.0), vec2(42.0, 42.0));
386:         grad_fill(p, ico, 21.0, alpha(a, 0.28), alpha(b, 0.14));
387:         self.ico(p, if warn { "danger-triangle" } else { "ssd-square" }, Ic::Filled, ico.center(), 22.0, b);
388:         let free = st.drive_free;
389:         let title = if st.drive_total > 0 { format!("{} used of {}", format_size(st.drive_total - st.drive_free), format_size(st.drive_total)) } else { format!("{} scanned", format_size(sn.total)) };
390:         p.text(pos2(ico.right() + 14.0, r.top() + 24.0), Align2::LEFT_CENTER, title, f_bold(T_TITLE), th.ink1);
391:         let sub = if st.drive_total > 0 {
392:             if warn {
