400:         p.text(pos2(ico.right() + 14.0, r.top() + 44.0), Align2::LEFT_CENTER, self.fit(p, &sub, &f_medium(T_META), r.width() - 340.0), f_medium(T_META), if warn { th.danger } else { th.ink3 });
401:         // gauge
402:         let bar = Rect::from_min_max(pos2(ico.right() + 14.0, r.bottom() - 18.0), pos2(r.right() - 300.0_f32.min(r.width() * 0.4), r.bottom() - 11.0));
403:         if bar.width() > 40.0 {
404:             well(p, &th, bar, 3.5);
405:             let grow = spring_to(ui.ctx(), "st-gauge", used, 160.0, 22.0).clamp(0.0, 1.0);
406:             let fill = Rect::from_min_size(bar.min, vec2((bar.width() * grow).max(7.0), 7.0));
407:             grad_fill(p, fill, 3.5, a, b);
408:             rim(p, fill, 3.5, 1.0, Color32::from_white_alpha(90), true, 6.0);
409:         }
410:         // reclaimable chip
411:         if sn.all > 0 {
412:             let t = format!("{} can be reclaimed", format_size(sn.safe.max(sn.all / 3)));
413:             let w = self.tw(p, &t, &f_semi(T_META)) + 40.0;
414:             let chip = Rect::from_min_size(pos2(r.right() - w - 16.0, r.top() + 14.0), vec2(w, 30.0));
415:             let resp = self.hit(ui, chip, "st-chip", Sense::click());
416:             grad_fill(p, chip, 15.0, alpha(th.good, if resp.hovered() { 0.28 } else { 0.18 }), alpha(th.good, 0.10));
417:             self.ico(p, "shield-check", Ic::Duo, pos2(chip.left() + 18.0, chip.center().y), 15.0, th.good);
418:             p.text(pos2(chip.left() + 32.0, chip.center().y), Align2::LEFT_CENTER, t, f_semi(T_META), th.good);
419:             if resp.clicked() {
420:                 self.push_act(Act::App("storage.view:1".into()));
421:             }
422:         }
423:         if !sn.finished {
424:             p.text(pos2(r.right() - 16.0, r.bottom() - 28.0), Align2::RIGHT_CENTER, format!("Scanning\u{2026} {} files", sn.files), f_medium(T_META), th.ink3);
425:         }
