516:     /// One junk candidate row. `check` = Some(checked) draws a checkbox. Returns true when the row body was clicked.
517:     fn junk_row(&mut self, ui: &Ui, p: &egui::Painter, r: Rect, j: &Junk, with_check: bool, key: &str, checked: Option<bool>) -> bool {
518:         let th = self.th.clone();
519:         let resp = self.hit(ui, r, (key, &j.path), Sense::click());
520:         let hv = self.anim(ui, (key, "h", &j.path), resp.hovered());
521:         elevate(p, &th, r, 14.0, 1);
522:         grad_fill(p, r, 14.0, th.card_top, th.card_bottom);
523:         if hv > 0.01 {
524:             p.rect_filled(r, cr(14.0), alpha(th.accent, 0.06 * hv));
525:         }
526:         rim(p, r, 14.0, 1.0, th.rim, true, 24.0);
527:         let mut x = r.left() + 14.0;
528:         if with_check {
529:             let on = checked.unwrap_or(false);
530:             let bx = Rect::from_center_size(pos2(x + 9.0, r.center().y), vec2(18.0, 18.0));
531:             let t = spring_to(ui.ctx(), ("stck", &j.path), if on { 1.0 } else { 0.0 }, 420.0, 28.0).clamp(0.0, 1.0);
532:             well(p, &th, bx, 6.0);
533:             if t > 0.02 {
534:                 let s = bx.shrink((1.0 - t) * 8.0);
535:                 let (a, b) = th.accent_grad();
536:                 grad_fill(p, s, 6.0, alpha(a, t), alpha(b, t));
537:                 self.ico(p, "check-read", Ic::Filled, bx.center(), 12.0 * t, Color32::from_white_alpha((255.0 * t) as u8));
538:             }
539:             x += 30.0;
540:         }
541:         let ic = Rect::from_center_size(pos2(x + 17.0, r.center().y), vec2(34.0, 34.0));
542:         let kc = self.safety_color(j.safety);
543:         grad_fill(p, ic, 11.0, alpha(kc, 0.20), alpha(kc, 0.08));
544:         self.ico(p, j.kind.icon(), Ic::Duo, ic.center(), 17.0, kc);
545:         let tx = ic.right() + 12.0;
546:         let right_w = 150.0;
547:         let max_w = (r.right() - tx - right_w - 12.0).max(60.0);
548:         p.text(pos2(tx, r.center().y - 9.0), Align2::LEFT_CENTER, self.fit(p, &j.name, &f_semi(T_BODY), max_w), f_semi(T_BODY), th.ink1);
549:         let sub = format!("{} \u{b7} {}", self.pretty_path(&Location::new(self.storage.as_ref().map(|s| s.fs.clone()).unwrap_or_default(), j.path.clone()).parent().unwrap_or_else(|| self.be.home())), j.reason);
550:         p.text(pos2(tx, r.center().y + 10.0), Align2::LEFT_CENTER, self.fit(p, &sub, &f_medium(T_META), max_w), f_medium(T_META), th.ink3);
551:         p.text(pos2(r.right() - 14.0, r.center().y - 9.0), Align2::RIGHT_CENTER, format_size(j.size()), f_bold(T_BODY), th.ink1);
552:         let badge = j.safety.label();
553:         let bw = self.tw(p, badge, &f_semi(10.0)) + 18.0;
554:         let br = Rect::from_min_size(pos2(r.right() - 14.0 - bw, r.center().y + 2.0), vec2(bw, 18.0));
555:         grad_fill(p, br, 9.0, alpha(kc, 0.22), alpha(kc, 0.12));
556:         p.text(br.center(), Align2::CENTER_CENTER, badge, f_semi(10.0), kc);
557:         if resp.hovered() {
558:             if let Some(cmd) = j.restore {
559:                 resp.clone().on_hover_text(format!("Comes back with: {cmd}"));
560:             }
561:         }
562:         if resp.secondary_clicked() {
563:             if let Some(loc) = Location::new(self.storage.as_ref().map(|s| s.fs.clone()).unwrap_or_default(), j.path.clone()).parent() {
564:                 self.push_act(Act::NewTab(Some(Route::Loc(loc))));
565:             }
566:         }
567:         resp.clicked()
568:     }
