570:     // ───────────── cleanup ─────────────
571:     fn storage_cleanup(&mut self, ui: &Ui, p: &egui::Painter, body: Rect, st: &mut StorageState, sn: &Snap) {
572:         let th = self.th.clone();
573:         // category chips
574:         let mut x = body.left();
575:         let mut y = body.top();
576:         let mut chips: Vec<(Option<JunkKind>, String, &'static str)> = vec![(None, format!("All \u{b7} {}", format_size(sn.all)), "layers-minimalistic")];
577:         for (k, s, n) in &sn.kinds {
578:             chips.push((Some(*k), format!("{} \u{b7} {} ({n})", k.label(), format_size(*s)), k.icon()));
579:         }
580:         for (k, label, icon) in chips {
581:             let w = self.tw(p, &label, &f_semi(T_META)) + 46.0;
582:             if x + w > body.right() {
583:                 x = body.left();
584:                 y += 38.0;
585:             }
586:             let r = Rect::from_min_size(pos2(x, y), vec2(w, 30.0));
587:             let on = st.filter == k;
588:             let resp = self.hit(ui, r, ("st-chip", format!("{:?}", k)), Sense::click());
589:             let a = self.anim(ui, ("st-chip-h", format!("{:?}", k)), resp.hovered());
590:             if on {
591:                 grad_fill(p, r, 15.0, th.accent_tint, th.accent_tint2);
592:                 rim(p, r, 15.0, 1.0, alpha(Color32::WHITE, if th.dark { 0.12 } else { 0.7 }), true, 14.0);
593:             } else {
594:                 raised(p, &th, r, 15.0, resp.hovered(), resp.is_pointer_button_down_on());
595:             }
596:             self.ico(p, icon, if on { Ic::Duo } else { Ic::Outline }, pos2(r.left() + 18.0, r.center().y), 14.0, if on { th.accent_ink } else { mix(th.ink3, th.ink1, a) });
597:             p.text(pos2(r.left() + 32.0, r.center().y), Align2::LEFT_CENTER, label, f_semi(T_META), if on { th.accent_ink } else { th.ink2 });
598:             if resp.clicked() {
599:                 st.filter = k;
600:             }
601:             x += w + 8.0;
602:         }
603:         y += 42.0;
604:         let foot_h = 54.0;
605:         let list = Rect::from_min_max(pos2(body.left(), y), pos2(body.right(), body.bottom() - foot_h - 8.0));
606:         let rows: Vec<&Junk> = sn.cands.iter().filter(|j| st.filter.map(|k| j.kind == k).unwrap_or(true)).collect();
607:         let row_h = 64.0;
608:         let content_h = rows.len() as f32 * row_h + 8.0;
609:         let off = self.vscroll(ui, list, "st-cleanup", content_h);
610:         let lp = p.with_clip_rect(list.expand2(vec2(2.0, 0.0)));
611:         if rows.is_empty() {
612:             let msg = if sn.finished { "Nothing to clean in this category." } else { "Looking for things you can clean\u{2026}" };
613:             lp.text(list.center(), Align2::CENTER_CENTER, msg, f_medium(T_BODY), th.ink3);
614:         }
615:         for (i, j) in rows.iter().enumerate() {
616:             let r = Rect::from_min_size(pos2(list.left(), list.top() + i as f32 * row_h - off), vec2(list.width() - 14.0, 56.0));
617:             if r.bottom() < list.top() - 4.0 || r.top() > list.bottom() + 4.0 {
618:                 continue;
619:             }
620:             let on = st.sel.contains(&j.path);
621:             if self.junk_row(ui, &lp, r, j, true, "st-row", Some(on)) {
622:                 if on {
623:                     st.sel.remove(&j.path);
624:                 } else {
625:                     st.sel.insert(j.path.clone());
626:                 }
627:             }
628:         }
629:         // sticky action bar
630:         let bar = Rect::from_min_size(pos2(body.left(), body.bottom() - foot_h), vec2(body.width(), foot_h));
631:         elevate(p, &th, bar, 18.0, 3);
632:         grad_fill(p, bar, 18.0, th.panel_top, th.panel_bottom);
633:         rim(p, bar, 18.0, 1.2, th.rim, true, 30.0);
634:         let sel_b: u64 = sn.cands.iter().filter(|j| st.sel.contains(&j.path)).map(|j| j.size()).sum();
635:         let msg = if st.sel.is_empty() { "Tick items to move them to the Trash. Nothing is deleted until you confirm.".to_string() } else { format!("{} selected \u{b7} frees {}", st.sel.len(), format_size(sel_b)) };
636:         p.text(pos2(bar.left() + 20.0, bar.center().y), Align2::LEFT_CENTER, self.fit(p, &msg, &f_semi(T_BODY), bar.width() - 420.0), f_semi(T_BODY), if st.sel.is_empty() { th.ink3 } else { th.ink1 });
637:         let mut rx = bar.right() - 14.0;
638:         let b3 = Rect::from_min_size(pos2(rx - 134.0, bar.center().y - 17.0), vec2(134.0, 34.0));
639:         if self.label_button(ui, b3, Some("trash-bin-minimalistic"), "Move to Trash", "st-trash", if st.sel.is_empty() { Btn::Raised } else { Btn::Danger }).clicked() && !st.sel.is_empty() {
640:             self.push_act(Act::App("storage.ask_clean".into()));
641:         }
642:         rx = b3.left() - 8.0;
643:         let b2 = Rect::from_min_size(pos2(rx - 112.0, bar.center().y - 17.0), vec2(112.0, 34.0));
644:         if self.label_button(ui, b2, Some("shield-check"), "Select safe", "st-selsafe", Btn::Raised).clicked() {
645:             st.sel = sn.cands.iter().filter(|j| j.safety == Safety::Safe).map(|j| j.path.clone()).collect();
646:         }
647:         if !st.sel.is_empty() {
648:             let b1 = Rect::from_min_size(pos2(b2.left() - 8.0 - 76.0, bar.center().y - 17.0), vec2(76.0, 34.0));
649:             if self.label_button(ui, b1, None, "Clear", "st-clear", Btn::Quiet).clicked() {
650:                 st.sel.clear();
651:             }
652:         }
653:     }
