655:     // ───────────── treemap ─────────────
656:     fn storage_map(&mut self, ui: &Ui, p: &egui::Painter, body: Rect, st: &mut StorageState) {
657:         let th = self.th.clone();
658:         let scan = st.scan.lock().unwrap();
659:         let focus = st.map_focus.min(scan.nodes.len() - 1);
660:         // breadcrumb
661:         let chain = scan.chain(focus);
662:         let mut x = body.left();
663:         let mut jump = None;
664:         for (i, n) in chain.iter().enumerate() {
665:             let label = if i == 0 { "Everything".to_string() } else { scan.nodes[*n].name.clone() };
666:             let w = self.tw(p, &label, &f_semi(T_META)) + 22.0;
667:             let r = Rect::from_min_size(pos2(x, body.top()), vec2(w, 28.0));
668:             let last = i + 1 == chain.len();
669:             let resp = self.hit(ui, r, ("st-mapcrumb", i), Sense::click());
670:             if last {
