760:     fn build_graph(scan: &Scan, focus: usize, th: &Theme) -> (Vec<GNode>, Vec<(usize, usize)>) {
761:         let root_size = scan.nodes[focus].size.max(1) as f32;
762:         let mut nodes: Vec<GNode> = vec![];
763:         let mut edges = vec![];
764:         let r_of = |s: u64| (3.0 + 30.0 * (s as f32 / root_size).sqrt()).clamp(3.0, 34.0);
765:         let seed = |i: usize| -> f32 {
766:             let mut h = (i as u32).wrapping_mul(2654435761);
767:             h ^= h >> 15;
768:             (h % 1000) as f32 / 1000.0
769:         };
770:         nodes.push(GNode { idx: Some(focus), label: scan.nodes[focus].name.clone(), path: scan.nodes[focus].path.clone(), size: scan.nodes[focus].size, pos: Vec2::ZERO, vel: Vec2::ZERO, r: 22.0, depth: 0, pinned: false, junk: false, is_dir: true, kind: Kind::Folder });
771:         let mut frontier = vec![(focus, 0usize)];
772:         while let Some((n, gi)) = frontier.first().cloned() {
773:             frontier.remove(0);
774:             let depth = nodes[gi].depth;
775:             if depth >= 4 || nodes.len() >= 190 {
776:                 continue;
777:             }
778:             let mut kids: Vec<usize> = scan.nodes[n].children.clone();
779:             kids.sort_by_key(|c| std::cmp::Reverse(scan.nodes[*c].size));
780:             for c in kids.into_iter().take(if depth == 0 { 12 } else { 6 }) {
781:                 let s = scan.nodes[c].size;
782:                 if (s as f32 / root_size) < 0.004 && depth > 0 {
783:                     continue;
784:                 }
785:                 let ang = seed(nodes.len()) * std::f32::consts::TAU;
786:                 let rad = 60.0 + 70.0 * (depth as f32 + 1.0);
787:                 let id = nodes.len();
788:                 nodes.push(GNode { idx: Some(c), label: scan.nodes[c].name.clone(), path: scan.nodes[c].path.clone(), size: s, pos: nodes[gi].pos + vec2(ang.cos(), ang.sin()) * rad * 0.5, vel: Vec2::ZERO, r: r_of(s), depth: depth + 1, pinned: false, junk: scan.nodes[c].junk.is_some(), is_dir: true, kind: Kind::Folder });
789:                 edges.push((gi, id));
790:                 frontier.push((c, id));
791:             }
792:             for f in scan.nodes[n].top_files.iter().take(2) {
793:                 if (f.size as f32 / root_size) < 0.01 || nodes.len() >= 190 {
794:                     continue;
795:                 }
796:                 let ang = seed(nodes.len() + 77) * std::f32::consts::TAU;
797:                 let id = nodes.len();
798:                 nodes.push(GNode { idx: None, label: f.name.clone(), path: f.path.clone(), size: f.size, pos: nodes[gi].pos + vec2(ang.cos(), ang.sin()) * 50.0, vel: Vec2::ZERO, r: r_of(f.size).min(14.0), depth: depth + 1, pinned: false, junk: false, is_dir: false, kind: f.kind });
799:                 edges.push((gi, id));
800:             }
801:         }
802:         let _ = th;
803:         (nodes, edges)
804:     }
