806:     fn graph_physics(g: &mut Graph) {
807:         let n = g.nodes.len();
808:         let mut force = vec![Vec2::ZERO; n];
809:         for i in 0..n {
810:             for j in (i + 1)..n {
811:                 let d = g.nodes[i].pos - g.nodes[j].pos;
812:                 let dist2 = d.length_sq().max(36.0);
813:                 let k = 2600.0 * (g.nodes[i].r + g.nodes[j].r) / 40.0;
814:                 let f = d / dist2.sqrt() * (k / dist2);
815:                 force[i] += f;
816:                 force[j] -= f;
817:             }
818:         }
819:         for (a, b) in &g.edges {
820:             let d = g.nodes[*b].pos - g.nodes[*a].pos;
821:             let dist = d.length().max(0.01);
822:             let rest = 46.0 + g.nodes[*a].r + g.nodes[*b].r;
823:             let f = d / dist * ((dist - rest) * 0.06);
824:             force[*a] += f;
825:             force[*b] -= f;
826:         }
827:         let mut energy = 0.0;
828:         for i in 0..n {
829:             let node = &mut g.nodes[i];
830:             if node.pinned {
831:                 node.vel = Vec2::ZERO;
832:                 continue;
833:             }
834:             let f = force[i] - node.pos * 0.012;
835:             node.vel = (node.vel + f * 0.9) * 0.82;
836:             if node.vel.length() > 14.0 {
837:                 node.vel = node.vel.normalized() * 14.0;
838:             }
839:             node.pos += node.vel;
840:             energy += node.vel.length_sq();
841:         }
842:         g.heat = (energy / n.max(1) as f32).sqrt();
843:     }
