86:             let mut n = 46.0 + self.tw(p, &i.label, &f) + 18.0;
87:             if !i.kbd.is_empty() {
88:                 n += self.tw(p, i.kbd, &f_medium(T_META)) + 18.0;
89:             }
90:             if !i.sub.is_empty() {
91:                 n += 18.0;
92:             }
93:             w = w.max(n);
94:         }
95:         w.max(items.iter().filter(|i| i.qrow).count() as f32 * 46.0 + 16.0).min(340.0)
96:     }
