308:     /// Context menus only show what applies: disabled rows disappear (their group gap moves on), and dense menus
309:     /// lift the quick actions into a row of icon buttons at the top.
310:     pub(crate) fn tidy_menu(items: Vec<MI>) -> Vec<MI> {
311:         let mut out: Vec<MI> = vec![];
312:         let mut carry = false;
313:         for mut it in items {
314:             if it.disabled {
315:                 carry |= it.gap;
316:                 continue;
317:             }
318:             if !it.sub.is_empty() {
319:                 it.sub = Self::tidy_menu(std::mem::take(&mut it.sub));
320:                 if it.sub.is_empty() {
321:                     carry |= it.gap;
322:                     continue;
323:                 }
324:             }
325:             if carry {
326:                 it.gap = true;
327:                 carry = false;
328:             }
329:             out.push(it);
330:         }
331:         if let Some(f) = out.first_mut() {
332:             f.gap = false;
333:         }
334:         let nq = out.iter().filter(|i| i.quick).count();
335:         if out.len() >= 11 && nq >= 2 {
336:             let (mut q, mut rest): (Vec<MI>, Vec<MI>) = out.into_iter().partition(|i| i.quick);
337:             q.truncate(6);
338:             for i in &mut q {
339:                 i.qrow = true;
340:                 i.gap = false;
341:             }
342:             if let Some(f) = rest.first_mut() {
343:                 f.gap = false;
344:             }
345:             q.extend(rest);
346:             return q;
347:         }
348:         out
349:     }
