359:     pub(crate) fn menu_height(items: &[MI]) -> f32 {
360:         PAD_Y * 2.0 + Self::qrow_h(items) + items.iter().filter(|i| !i.qrow).map(|i| ITEM_H + if i.gap { GAP } else { 0.0 }).sum::<f32>()
361:     }
362: 
363:     /// y offset (from the menu top) of row `idx`.
364:     pub(crate) fn menu_row_y(items: &[MI], idx: usize) -> f32 {
365:         PAD_Y + Self::qrow_h(items) + items.iter().take(idx).filter(|i| !i.qrow).map(|i| ITEM_H + if i.gap { GAP } else { 0.0 }).sum::<f32>() + if items[idx].gap { GAP } else { 0.0 }
366:     }
