368:     pub(crate) fn paint_menu(&mut self, ui: &mut Ui, pos: Pos2, items: &[MI], width: f32, id: &str, open_sub: Option<usize>) -> (Rect, Option<usize>, Option<Act>) {
369:         let th = self.th.clone();
370:         let p = ui.painter().clone();
371:         let h = Self::menu_height(items);
372:         let r = Rect::from_min_size(pos, vec2(width, h));
373:         menu_surface(&p, &th, r, 18.0);
374:         ui.allocate_rect(r, Sense::hover());
375:         let mut y = r.top() + PAD_Y;
376:         let mut chosen = None;
377:         let mut hover_sub = None;
378:         // ── quick-action row (dense menus)
379:         let qn = items.iter().filter(|i| i.qrow).count();
380:         if qn > 0 {
381:             let cw = (width - 12.0) / qn as f32;
382:             for (k, (i, it)) in items.iter().enumerate().filter(|(_, i)| i.qrow).enumerate() {
383:                 let cell = Rect::from_min_size(pos2(r.left() + 6.0 + cw * k as f32 + 2.0, y), vec2(cw - 4.0, QROW_H));
384:                 let resp = ui.interact(cell, Id::unique((id, i, "q")), Sense::click());
385:                 let hv = self.anim(ui, (id, i, "qa"), resp.hovered());
386:                 let down = resp.is_pointer_button_down_on();
387:                 if down {
388:                     grad_fill(&p, cell, 11.0, alpha(th.shadow, if th.dark { 0.34 } else { 0.10 }), alpha(th.shadow, if th.dark { 0.2 } else { 0.05 }));
389:                     rim(&p, cell, 11.0, 3.0, alpha(th.shadow, if th.dark { 0.35 } else { 0.10 }), true, 12.0);
390:                 } else {
391:                     raised(&p, &th, cell, 11.0, resp.hovered(), false);
392:                 }
393:                 let col = if it.danger { th.danger } else { mix(th.ink2, if th.dark { th.ink1 } else { th.accent_ink }, hv) };
394:                 self.ico(&p, it.icon, if hv > 0.5 { Ic::Duo } else { Ic::Outline }, cell.center() + if down { vec2(0.0, 0.6) } else { vec2(0.0, 0.0) }, 18.0, col);
395:                 let tip = if it.kbd.is_empty() { it.label.clone() } else { format!("{}   {}", it.label, it.kbd) };
396:                 resp.clone().on_hover_text(tip);
397:                 if resp.clicked() && it.act.is_some() {
398:                     chosen = it.act.clone();
399:                 }
400:             }
401:             y += QROW_H + 8.0;
402:         }
403:         for (i, it) in items.iter().enumerate() {
404:             if it.qrow {
405:                 continue;
406:             }
407:             if it.gap {
408:                 y += GAP;
409:             }
410:             let row = Rect::from_min_size(pos2(r.left() + 6.0, y), vec2(width - 12.0, ITEM_H));
411:             let resp = ui.interact(row, Id::unique((id, i)), if it.disabled { Sense::hover() } else { Sense::click() });
412:             let hov = !it.disabled && (resp.hovered() || open_sub == Some(i));
413:             let hv = self.anim(ui, (id, i, "mi"), hov);
414:             let down = hov && resp.is_pointer_button_down_on();
415:             if down {
416:                 // pressed: the row sinks into the surface
417:                 grad_fill(&p, row, 9.0, alpha(th.shadow, if th.dark { 0.32 } else { 0.10 }), alpha(th.shadow, if th.dark { 0.18 } else { 0.05 }));
418:                 rim(&p, row, 9.0, 3.0, alpha(th.shadow, if th.dark { 0.35 } else { 0.11 }), true, 12.0);
419:             } else if hv > 0.01 {
420:                 // hover / open: a softly raised tile lit from above
421:                 let (t0, t1) = if it.danger {
422:                     (alpha(th.danger, 0.18), alpha(th.danger, 0.08))
423:                 } else if th.dark {
424:                     (c(255, 255, 255, 0.15), c(255, 255, 255, 0.06))
425:                 } else {
426:                     (alpha(th.accent, 0.14), alpha(th.accent, 0.07))
427:                 };
428:                 shadow(&p, row, 9.0, 1.5, 4.0, -1.0, alpha(th.shadow, (if th.dark { 0.30 } else { 0.09 }) * hv));
429:                 grad_fill(&p, row, 9.0, alpha(t0, hv), alpha(t1, hv));
430:                 rim(&p, row, 9.0, 1.0, alpha(Color32::WHITE, (if th.dark { 0.18 } else { 0.95 }) * hv), true, 14.0);
431:                 rim(&p, row, 9.0, 1.0, alpha(th.shadow, (if th.dark { 0.30 } else { 0.05 }) * hv), false, 5.0);
432:             } else if it.tog && it.checked {
433:                 // on-state rows keep a faint recessed accent wash
434:                 grad_fill(&p, row, 9.0, alpha(th.accent, 0.07), alpha(th.accent, 0.03));
435:             }
436:             let col = if it.disabled { alpha(th.ink2, 0.38) } else if it.danger { th.danger } else { th.ink1 };
437:             let ic = pos2(row.left() + 19.0, row.center().y);
438:             if let Some(dot) = it.dot {
439:                 grad_fill(&p, Rect::from_center_size(ic, vec2(9.0, 9.0)), 4.5, mix(dot, Color32::WHITE, 0.25), dot);
440:             } else {
441:                 self.ico(&p, it.icon, if hv > 0.5 { Ic::Duo } else { Ic::Outline }, ic, 16.0, if it.disabled { alpha(th.ink3, 0.4) } else if it.danger { th.danger } else { mix(th.ink3, if th.dark { th.ink1 } else { th.accent_ink }, hv) });
442:             }
443:             let right_reserve = if !it.sub.is_empty() { 24.0 } else if !it.kbd.is_empty() { self.tw(&p, it.kbd, &f_medium(T_META)) + 22.0 } else if it.tog { 26.0 } else { 12.0 };
444:             let label = self.fit(&p, &it.label, &f_medium(T_BODY), (row.width() - 40.0 - right_reserve).max(20.0));
445:             p.text(pos2(row.left() + 36.0, row.center().y + if down { 0.6 } else { 0.0 }), Align2::LEFT_CENTER, label, f_medium(T_BODY), col);
446:             if !it.sub.is_empty() {
447:                 let c = pos2(row.right() - 13.0, row.center().y);
448:                 let s = egui::Stroke::new(1.5, th.ink4);
449:                 p.line_segment([c + vec2(-1.5, -3.5), c + vec2(2.0, 0.0)], s);
450:                 p.line_segment([c + vec2(2.0, 0.0), c + vec2(-1.5, 3.5)], s);
451:                 if hov {
452:                     hover_sub = Some(i);
453:                 }
454:             } else if it.tog {
455:                 let c = pos2(row.right() - 17.0, row.center().y);
456:                 if it.checked {
457:                     self.ico(&p, "check-circle", Ic::Filled, c, 15.0, if it.disabled { alpha(th.accent, 0.4) } else { th.accent });
458:                 } else {
459:                     // switched off: the tick stays, greyed, so the row still reads as a toggle
460:                     self.ico(&p, "check-circle", Ic::Outline, c, 15.0, alpha(th.ink4, if hov { 0.7 } else { 0.38 }));
461:                 }
462:             } else if !it.kbd.is_empty() {
463:                 p.text(pos2(row.right() - 12.0, row.center().y), Align2::RIGHT_CENTER, it.kbd, f_medium(T_META), th.ink4);
464:             }
465:             if resp.clicked() && it.act.is_some() && !it.disabled {
466:                 chosen = it.act.clone();
467:             }
468:             y += ITEM_H;
469:         }
470:         (r, hover_sub, chosen)
