473:     pub fn draw_menu(&mut self, ctx: &Context) {
474:         let Some(mut m) = self.menu.clone() else { return };
475:         let screen = ctx.content_rect().intersect(win_rect().expand(0.0));
476:         let items = Self::tidy_menu(self.menu_items(&m));
477:         if items.is_empty() {
478:             self.menu = None;
479:             return;
480:         }
481:         let measure = ctx.debug_painter();
482:         let w = self.menu_width(&measure, &items, 238.0);
483:         let h = Self::menu_height(&items);
484:         let mut pos = m.pos;
485:         if matches!(m.kind, MenuKind::More | MenuKind::Sort) {
486:             pos.x -= w;
487:         }
488:         pos.x = pos.x.min(screen.right() - w - 10.0).max(screen.left() + 8.0);
489:         pos.y = if pos.y + h > screen.bottom() - 10.0 { (screen.bottom() - h - 10.0).max(8.0) } else { pos.y };
490:         // spring pop-in: slides a few px with a touch of overshoot while fading up
491:         let pop = if self.lib(|l| l.settings.reduce_motion) { 1.0 } else { spring_out(m.age) };
492:         pos.y += (1.0 - pop) * -9.0;
493:         if m.age < 0.5 {
494:             ctx.request_repaint();
495:         }
496:         let mut chosen: Option<Act> = None;
497:         let mut inside_any = false;
498:         let mut next_sub = m.sub;
499:         egui::Area::new(Id::unique("ctx-menu")).order(Order::Foreground).fixed_pos(screen.min).interactable(true).show(ctx, |ui| {
500:             ui.set_clip_rect(screen);
501:             ui.set_opacity((m.age * 9.0).clamp(0.0, 1.0));
502:             let bg = ui.allocate_rect(screen, Sense::click());
503:             let (r, hs, act) = self.paint_menu(ui, pos, &items, w, "m", next_sub);
504:             inside_any = ui.rect_contains_pointer(r);
505:             chosen = act;
506:             // submenu (kept open while the pointer is over the parent row or the submenu itself)
507:             if let Some(si) = hs.or(next_sub) {
508:                 if let Some(row) = items.get(si) {
509:                     if !row.sub.is_empty() {
510:                         let row_y = pos.y + Self::menu_row_y(&items, si);
511:                         let sw = self.menu_width(&ui.painter().clone(), &row.sub, 220.0);
512:                         let sh = Self::menu_height(&row.sub);
513:                         let mut sp = pos2(r.right() + 4.0, row_y);
514:                         if sp.x + sw > screen.right() - 8.0 {
515:                             sp.x = r.left() - sw - 4.0;
516:                         }
517:                         sp.y = sp.y.min(screen.bottom() - sh - 10.0).max(8.0);
518:                         let (sr, _, sact) = self.paint_menu(ui, sp, &row.sub, sw, "ms", None);
519:                         if sact.is_some() {
520:                             chosen = sact;
521:                         }
522:                         let over_row = ui.rect_contains_pointer(Rect::from_min_size(pos2(r.left(), row_y), vec2(w, ITEM_H)));
523:                         let over_sub = ui.rect_contains_pointer(sr);
524:                         inside_any = inside_any || over_sub;
525:                         next_sub = if hs.is_some() || over_sub || (over_row && next_sub.is_some()) { Some(si) } else { None };
526:                     }
527:                 }
528:             } else {
529:                 next_sub = None;
530:             }
531:             if bg.clicked() && !inside_any {
532:                 self.menu = None;
533:             }
534:         });
535:         if let Some(m) = self.menu.as_mut() {
536:             m.sub = next_sub;
537:             m.age += 0.016;
538:         }
539:         if let Some(a) = chosen {
540:             self.menu = None;
541:             self.acts.push(a);
542:         }
543:     }
