546:     pub fn draw_toasts(&mut self, ctx: &Context) {
547:         let dt = ctx.input(|i| i.stable_dt).min(0.1);
548:         for t in &mut self.toasts {
549:             t.age += dt;
550:         }
551:         self.toasts.retain(|t| t.age < 3.8);
552:         for j in &mut self.jobs {
553:             j.age += dt;
554:         }
555:         self.jobs.retain(|j| j.state == JobState::Running || j.age < 0.1);
556:         if self.toasts.is_empty() {
557:             return;
558:         }
559:         ctx.request_repaint();
560:         let win = win_rect();
561:         let th = self.th.clone();
562:         egui::Area::new(Id::unique("toasts")).order(Order::Tooltip).fixed_pos(win.min).interactable(false).show(ctx, |ui| {
563:             let p = ui.painter().clone();
564:             let mut y = win.bottom() - STATUS_H - 18.0;
565:             for t in self.toasts.iter().rev() {
566:                 let a = (1.0 - ((t.age - 3.2) / 0.6).clamp(0.0, 1.0)).min((t.age / 0.18).clamp(0.0, 1.0));
567:                 let f = f_semi(T_BODY);
568:                 let w = (self.tw(&p, &t.text, &f) + 62.0).min(win.width() - 40.0);
569:                 let r = Rect::from_center_size(pos2(win.center().x + 126.0 * self.sidebar_open, y - 20.0 + (1.0 - a) * 10.0), vec2(w, 40.0));
570:                 let sh = |c: Color32| alpha(c, a);
571:                 shadow(&p, r, 20.0, 12.0, 30.0, -8.0, sh(alpha(th.shadow, if th.dark { 0.7 } else { 0.35 })));
572:                 grad_fill(&p, r, 20.0, sh(if th.dark { c(40, 50, 70, 0.98) } else { c(28, 38, 58, 0.97) }), sh(if th.dark { c(26, 34, 50, 0.98) } else { c(20, 28, 44, 0.97) }));
573:                 rim(&p, r, 20.0, 1.2, sh(c(255, 255, 255, 0.28)), true, 24.0);
574:                 self.ico(&p, if t.ok { "check-circle" } else { "info-circle" }, Ic::Filled, pos2(r.left() + 22.0, r.center().y), 16.0, sh(if t.ok { hex("#59c79a") } else { hex("#ff7a84") }));
575:                 let s = self.fit(&p, &t.text, &f, w - 62.0);
576:                 p.text(pos2(r.left() + 40.0, r.center().y), Align2::LEFT_CENTER, s, f, sh(hex("#f4f7fd")));
577:                 y -= 48.0;
578:             }
579:         });
580:     }
