613:             if let Some(h) = hint {
614:                 p.text(pos2(r.left() + 12.0, r.bottom() - 12.0), Align2::LEFT_CENTER, self.fit(&p, &h, &f_medium(10.5), w - 24.0), f_medium(10.5), th.accent_ink);
615:             }
616:         });
