721:         let mut settings: Vec<(&'static str, String, String, Act, &'static str)> = vec![
722:             ("settings-minimalistic", "Settings".into(), "Open the full settings page".into(), Act::Settings, "Ctrl ,"),
723:             ("stars-minimalistic", if st.dark { "Light appearance" } else { "Dark appearance" }.into(), "Theme".into(), Act::ToggleTheme, "D"),
724:             ("eye", "Hidden files".into(), if st.show_hidden { "Currently shown" } else { "Currently hidden" }.into(), Act::ToggleHidden, "Ctrl H"),
