727:             ("widget", "Wallpaper".into(), "Desktop surface".into(), Act::Modal(Modal::Wallpaper), ""),
728:         ];
729:         let mut files: Vec<(&'static str, String, String, Act, &'static str)> = vec![];
730:         if q.len() >= 2 {
731:             for h in self.palette.hits.iter().take(8) {
732:                 let act = if h.entry.is_dir { Act::Nav(Route::Loc(h.entry.loc.clone())) } else { Act::Open(h.entry.loc.clone()) };
733:                 files.push((h.entry.kind.icon(), h.entry.name.clone(), h.entry.loc.parent().map(|p| self.pretty_path(&p)).unwrap_or_default(), act, if h.entry.is_dir { "" } else { "Open" }));
734:             }
735:         }
736:         let score = |s: &str| -> Option<i32> {
737:             let s = s.to_lowercase();
738:             if q.is_empty() {
739:                 return Some(0);
740:             }
741:             if let Some(i) = s.find(&q) {
742:                 return Some(1000 - i as i32);
743:             }
744:             let mut it = s.chars();
745:             let mut n = 0;
746:             for qc in q.chars() {
747:                 n += 1;
748:                 it.find(|c| *c == qc)?;
749:             }
750:             Some(100 - n)
751:         };
752:         let filt = |v: Vec<(&'static str, String, String, Act, &'static str)>, limit: usize| -> Vec<(&'static str, String, String, Act, &'static str)> {
753:             let mut s: Vec<_> = v.into_iter().filter_map(|x| score(&format!("{} {}", x.1, x.2)).map(|sc| (sc, x))).collect();
754:             s.sort_by_key(|x| -x.0);
755:             s.into_iter().take(limit).map(|x| x.1).collect()
756:         };
757:         let mut out: Vec<(usize, String, Vec<(&'static str, String, String, Act, &'static str)>)> = vec![];
758:         let want = |i: usize| cat == 0 || cat == i;
759:         if want(1) {
760:             let v = filt(selection, if q.is_empty() { 4 } else { 6 });
761:             if !v.is_empty() {
762:                 out.push((1, "Selection".into(), v));
763:             }
764:         }
765:         if want(2) {
766:             let v = filt(commands.drain(..).collect(), 7);
767:             if !v.is_empty() {
768:                 out.push((2, if q.is_empty() { "Suggested" } else { "Commands" }.to_string(), v));
769:             }
770:         }
771:         if want(3) {
772:             let v = filt(places, 6);
773:             if !v.is_empty() {
774:                 out.push((3, "Navigate".into(), v));
775:             }
776:         }
777:         if want(4) && !files.is_empty() {
778:             out.push((4, "Files & folders".into(), files));
779:         }
780:         if want(5) {
781:             let v = filt(settings.drain(..).collect(), 6);
782:             if !v.is_empty() {
783:                 out.push((5, "Preferences".into(), v));
784:             }
