384: /// `#terminal=ls;neofetch`, `#photos`, `#photo` / `#photo=edit` / `#photo=info`, `#menu` — open the suite in a given state
385: /// (handy for sharing a view and for automated screenshots).
386: #[cfg(target_arch = "wasm32")]
387: fn deep_link(a: &mut SmartApp) {
388:     use crate::shell::AppId;
389:     let h = web_sys::window().and_then(|w| w.location().hash().ok()).unwrap_or_default();
390:     let h = h.trim_start_matches('#');
391:     let (name, arg) = h.split_once('=').unwrap_or((h, ""));
392:     match name {
393:         "terminal" => {
394:             a.open_app(AppId::Terminal);
395:             a.shell.term.command("new");
396:             for c in arg.split(';').filter(|c| !c.is_empty()) {
397:                 a.term_submit(0, c.replace("%20", " "));
398:             }
399:         }
400:         "photos" => a.open_app(AppId::Photos),
401:         "top" => {
402:             a.open_app(AppId::Terminal);
403:             a.shell.term.command("new");
404:             a.term_submit(0, "top".into());
405:         }
406:         "palette" => {
407:             match arg {
408:                 "photos" => a.open_app(AppId::Photos),
409:                 "terminal" => a.open_app(AppId::Terminal),
410:                 _ => {}
411:             }
412:             a.act(Act::Palette);
413:         }
414:         "settings" => {
415:             let app = if arg == "terminal" { AppId::Terminal } else { AppId::Photos };
416:             a.open_app(app);
417:             a.shell.settings = Some((app, 0));
418:         }
419:         "photomenu" => {
420:             a.open_app(AppId::Photos);
421:             if arg == "viewer" {
422:                 if let Some(l) = a.photos_first() {
423:                     a.photos_show(l);
424:                 }
425:                 let items = a.photos_viewer_menu();
426:                 a.open_app_menu(egui::pos2(760.0, 300.0), items);
427:             } else {
428:                 let items = a.photos_library_menu();
429:                 a.open_app_menu(egui::pos2(760.0, 300.0), items);
430:             }
431:         }
432:         "termmenu" => {
433:             a.open_app(AppId::Terminal);
434:             a.shell.term.command("new");
435:             a.term_submit(0, "ls".into());
436:             let items = a.term_menu_main();
437:             a.open_app_menu(egui::pos2(900.0, 300.0), items);
438:         }
439:         "photo" => {
440:             a.open_app(AppId::Photos);
441:             let first = a.photos_first();
442:             if let Some(l) = first {
443:                 a.photos_show(l);
444:             }
445:             a.shell.photos.edit = arg == "edit";
446:             a.shell.photos.info = arg == "info";
447:             if arg == "edit" {
448:                 a.shell.photos.adj = crate::photos::Adjust { exposure: 0.1, contrast: 0.25, saturation: 0.3, warmth: 0.3, vignette: 0.4 };
449:                 a.shell.photos.dirty = true;
450:             }
451:         }
452:         "copy" => {
453:             // starts the paced 5 GB demo transfer so the dialog can be seen straight away
454:             let mut stack = vec![a.be.home()];
455:             let mut found = None;
456:             while let Some(d) = stack.pop() {
457:                 if let Some(fs) = a.be.registry.get(&d.fs) {
458:                     if let Ok(l) = fs.list(&d.path) {
459:                         for e in l {
460:                             if e.paced {
461:                                 found = Some(e.loc.clone());
462:                             } else if e.is_dir {
463:                                 stack.push(e.loc.clone());
464:                             }
465:                         }
466:                     }
467:                 }
468:                 if found.is_some() {
469:                     break;
470:                 }
471:             }
472:             let dest = a.places.iter().find(|p| p.id == "downloads").map(|p| p.loc.clone());
473:             if let (Some(src), Some(d)) = (found, dest) {
474:                 a.submit_job(smart_core::JobKind::Copy { srcs: vec![src], dest: d });
475:             }
476:         }
477:         "menu" => {
478:             a.menu = Some(Menu { kind: MenuKind::More, pos: egui::pos2(1250.0, 130.0), target: None, device: None, sub: None, age: 0.0 });
479:         }
480:         _ => {}
481:     }
482: }
